export const m75CanonicalJson=m71CanonicalJson
export class M75ValidationError extends Error {}
const fail=(message='Invalid controlled-fleet request.'):never=>{throw new M75ValidationError(message)}
const require: (condition:unknown,message?:string)=>asserts condition=(condition,message)=>{if(!condition)fail(message)}
const keys=(value:unknown,names:string[])=>{try{m71Keys(value,names)}catch{fail('Unexpected or missing controlled-fleet fields.')}}
const text=(value:unknown,max=500):string=>{require(typeof value==='string');const out=(value as string).trim().normalize('NFC');require(out.length>0&&Array.from(out).length<=max&&!/[\u0000-\u001f\u007f-\u009f\ud800-\udfff]/u.test(out));return out}
const nullableText=(value:unknown,max=500)=>value===null?null:text(value,max)
const uuidOrNull=(value:unknown)=>{require(value===null||m71Uuid(value));return value as string|null}
const period=(value:unknown)=>{keys(value,['start','endExclusive']);const out=value as {start:unknown;endExclusive:unknown},valid=(v:unknown):v is string=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&(()=>{const [y,m,d]=v.split('-').map(Number),date=new Date(Date.UTC(y!,m!-1,d!));return date.getUTCFullYear()===y&&date.getUTCMonth()===m!-1&&date.getUTCDate()===d})();require(valid(out.start)&&valid(out.endExclusive)&&out.start<out.endExclusive);return {start:out.start,endExclusive:out.endExclusive}}
const normalizedId=(value:unknown)=>value===null?null:m74AssetId(value)

function asset(value:unknown):M75RosterAsset{
 keys(value,['rowId','assetId','aliases','entityId','facilityId','period','mode','vehicleClass','modelYear','fuel','controlBasis','classificationBasis','controlExplanation']);const v=structuredClone(value) as M75RosterAsset
 require(m71Uuid(v.rowId));v.assetId=normalizedId(v.assetId);require(Array.isArray(v.aliases)&&v.aliases.length<=8);v.aliases=v.aliases.map(m74AssetId).sort();require(new Set(v.aliases).size===v.aliases.length&&!v.aliases.includes(v.assetId??''));v.entityId=uuidOrNull(v.entityId);v.facilityId=uuidOrNull(v.facilityId);v.period=v.period===null?null:period(v.period);require(['on_road','off_road','rail','marine','air','other','unknown'].includes(v.mode));v.vehicleClass=nullableText(v.vehicleClass,100);require(v.modelYear===null||Number.isInteger(v.modelYear)&&v.modelYear>=1900&&v.modelYear<=2100);v.fuel=nullableText(v.fuel,100);require(['owned_operational_control_full_year','other_control_arrangement','unknown'].includes(v.controlBasis));v.classificationBasis=nullableText(v.classificationBasis);v.controlExplanation=nullableText(v.controlExplanation);return v
}
function statement(value:unknown):M75StatementInput{
 keys(value,['issuer','reference','description','discoveryBasis','coveredEntityIds','completeness','allTripLocationsIncluded','assets']);const v=structuredClone(value) as M75StatementInput
 v.issuer=text(v.issuer,120);v.reference=text(v.reference,120);v.description=text(v.description,2000);v.discoveryBasis=text(v.discoveryBasis,2000);require(Array.isArray(v.coveredEntityIds)&&v.coveredEntityIds.every(m71Uuid));v.coveredEntityIds=[...new Set(v.coveredEntityIds)].sort();require(['declared_complete','partial','unknown'].includes(v.completeness)&&typeof v.allTripLocationsIncluded==='boolean'&&Array.isArray(v.assets)&&v.assets.length<=M75_MAX_ASSETS);v.assets=v.assets.map(asset);require(new Set(v.assets.map(x=>x.rowId)).size===v.assets.length);return v
}
export function validateM75Save(value:unknown):M75SaveInput{
 keys(value,['profile','coverageVersionId','coverageVersionSha256','expectedDependencySha256','period','rosterStatement','manualConfirmation','links','expectedVersionId','expectedVersionSha256','correctionReason','idempotencyKey']);const v=structuredClone(value) as M75SaveInput
 require(v.profile===M75_PROFILE&&m71Uuid(v.coverageVersionId)&&m71HashString(v.coverageVersionSha256)&&m71HashString(v.expectedDependencySha256)&&m71Uuid(v.idempotencyKey)&&typeof v.manualConfirmation==='boolean');v.period=period(v.period);require(m75CanonicalJson(v.period)===m75CanonicalJson(M75_PERIOD));v.rosterStatement=v.rosterStatement===null?null:statement(v.rosterStatement);require(Array.isArray(v.links));v.links=v.links.map(raw=>{keys(raw,['rowId','sourceId']);const link=raw as M75Link;require(m71Uuid(link.rowId));return {rowId:link.rowId,sourceId:uuidOrNull(link.sourceId)}});require(new Set(v.links.map(x=>x.rowId)).size===v.links.length);if(v.rosterStatement)require(m75CanonicalJson(v.links.map(x=>x.rowId).sort())===m75CanonicalJson(v.rosterStatement.assets.map(x=>x.rowId).sort()));else require(v.links.length===0)
 if(v.expectedVersionId===null)require(v.expectedVersionSha256===null&&v.correctionReason===null);else{require(m71Uuid(v.expectedVersionId)&&m71HashString(v.expectedVersionSha256));v.correctionReason=text(v.correctionReason)}return v
}
export function validateM75Review(value:unknown):M75ReviewInput{keys(value,['versionId','expectedVersionSha256','expectedDependencySha256','decision','note','acknowledgedLimitations','idempotencyKey']);const v=structuredClone(value) as M75ReviewInput;require(m71Uuid(v.versionId)&&m71HashString(v.expectedVersionSha256)&&m71HashString(v.expectedDependencySha256)&&m71Uuid(v.idempotencyKey)&&['accepted_bounded_reconciliation','changes_requested'].includes(v.decision)&&m75CanonicalJson(v.acknowledgedLimitations)===m75CanonicalJson(M75_LIMITATIONS));v.note=text(v.note);return v}
export function validateM75Report(value:unknown):M75ReportInput{keys(value,['expectedReconciliationSha256','idempotencyKey']);const v=structuredClone(value) as M75ReportInput;require(m71HashString(v.expectedReconciliationSha256)&&m71Uuid(v.idempotencyKey));return v}
export function m75Activity(input:M75SaveInput):M75Activity{const {expectedDependencySha256:_,expectedVersionId:__,expectedVersionSha256:___,correctionReason:____,idempotencyKey:_____,...activity}=input;return activity}
export const m75DependencyPayload=(value:Pick<M75Dependencies,'coveragePin'|'coverageReviewPin'|'workpaperPins'>)=>({coveragePin:value.coveragePin,coverageReviewPin:value.coverageReviewPin,workpaperPins:value.workpaperPins})
