export function m75StatementText(activity:M75Activity,coverage:M71Version):string{require(activity.rosterStatement!==null);return 'SYNTHETIC — NOT AN ORIGINAL COMPANY RECORD OR INDEPENDENT MEASUREMENT\n'+m75CanonicalJson({profile:'m75-synthetic-roster-statement-v1',companyLabel:coverage.snapshot.companyLabel,coverageVersionId:coverage.id,coverageVersionSha256:coverage.versionSha256,period:activity.period,statement:activity.rosterStatement})+'\n'}

export function deriveM75RosterFindings(activity:M75Activity,coverage:M71Version):M75Finding[]{
 const out:M75Finding[]=[],add=(code:string,rowKey:string|null,message:string)=>out.push({code,rowKey,message,blocking:true}),s=activity.rosterStatement
 if(!s){add('roster_statement_missing',null,'The declared controlled-vehicle roster statement is missing.');return out}if(!activity.manualConfirmation)add('roster_unconfirmed',null,'Confirm the complete synthetic roster declaration.');if(!s.assets.length)add('roster_empty',null,'An empty roster cannot establish a zero fleet.');if(s.completeness!=='declared_complete')add('roster_not_declared_complete',null,'The roster population is partial or unknown.');if(!s.allTripLocationsIncluded)add('trip_locations_incomplete',null,'The roster declaration must cover all trip locations, including interstate travel.');const entities=coverage.snapshot.entities.map(x=>x.id).sort();if(m75CanonicalJson(s.coveredEntityIds)!==m75CanonicalJson(entities))add('entity_population_incomplete',null,'Every entity in the bound corporate register needs a roster population declaration.')
 const links=new Map(activity.links.map(x=>[x.rowId,x.sourceId])),identities=new Map<string,string[]>(),sourceRows=new Map<string,string[]>();for(const a of s.assets){const key='roster:'+a.rowId,ids=[...(a.assetId?[a.assetId]:[]),...a.aliases];for(const id of ids)identities.set(id,[...(identities.get(id)??[]),a.rowId]);const source=links.get(a.rowId);if(source)sourceRows.set(source,[...(sourceRows.get(source)??[]),a.rowId]);if(a.entityId&&!coverage.snapshot.entities.some(x=>x.id===a.entityId))add('unknown_entity',key,'The declared entity is not in the bound corporate register.');if(a.facilityId&&!coverage.snapshot.facilities.some(x=>x.id===a.facilityId&&(!a.entityId||x.entityId===a.entityId)))add('facility_conflict',key,'The declared facility is missing or belongs to another entity.');if(source&&!coverage.snapshot.sources.some(x=>x.id===source&&x.domain==='mobile_combustion'))add('source_conflict',key,'The mapped source is missing or is not mobile combustion.');if(!a.assetId)add('asset_identity_unknown',key,'Stable vehicle identity is unknown.');if(!a.entityId||!a.facilityId||!a.period||a.mode==='unknown'||!a.vehicleClass||a.modelYear===null||!a.fuel||a.controlBasis==='unknown'||!a.classificationBasis||!a.controlExplanation)add('vehicle_facts_unknown',key,'One or more required vehicle, period, classification or control facts are unknown.');const supported=a.mode==='on_road'&&a.vehicleClass==='Medium- and Heavy-Duty Vehicles'&&a.modelYear!==null&&a.modelYear>=2007&&a.modelYear<=2022&&a.fuel==='Fossil Diesel'&&a.controlBasis==='owned_operational_control_full_year'&&m75CanonicalJson(a.period)===m75CanonicalJson(M75_PERIOD);if(!supported&&a.assetId&&a.mode!=='unknown'&&a.vehicleClass&&a.modelYear!==null&&a.fuel&&a.controlBasis!=='unknown'&&a.period)add('vehicle_profile_unsupported',key,'The controlled vehicle is outside the current M74 candidate profile.');if(!source)add('source_missing',key,'No current corporate mobile source is mapped to this roster row.')}
 for(const [id,rows] of identities)if(rows.length>1)for(const row of rows)add('duplicate_asset_identity','roster:'+row,`Declared asset identity ${id} appears in multiple roster rows.`);for(const [id,rows] of sourceRows)if(rows.length>1)for(const row of rows)add('duplicate_source_mapping','roster:'+row,`Corporate mobile source ${id} is mapped to multiple roster rows.`);return out
}

export function buildM75Dependencies(coverage:M71Version|null,workpapers:M74Version[],hash:(value:unknown)=>string):M75Dependencies{const pins:M75WorkpaperPin[]=workpapers.map(v=>({worksheetId:v.worksheetId,sourceId:v.activity.binding.sourceId,assetId:v.activity.vehicle.assetId,version:{id:v.id,sha256:v.versionSha256},decision:v.review?{id:v.review.id,sha256:v.review.decisionSha256}:null})).sort((a,b)=>a.worksheetId.localeCompare(b.worksheetId));const value={coveragePin:coverage?{id:coverage.id,sha256:coverage.versionSha256}:null,coverageReviewPin:coverage?.review?{id:coverage.review.id,sha256:coverage.review.decisionSha256}:null,workpaperPins:pins};return {...value,dependencySha256:hash(m75DependencyPayload(value))}}

const rowStatus=(findings:M75Finding[])=>{const codes=new Set(findings.filter(x=>x.blocking).map(x=>x.code));if([...codes].some(x=>x.startsWith('duplicate_')))return 'duplicate';if(codes.has('vehicle_profile_unsupported'))return 'unsupported';if([...codes].some(x=>x.includes('unknown')||x.includes('unconfirmed')))return 'unknown';if(codes.has('orphan_source'))return 'orphan_source';if(codes.has('orphan_workpaper'))return 'orphan_workpaper';if(codes.has('source_missing'))return 'missing_source';if([...codes].some(x=>x.includes('stale')))return 'stale';if(codes.has('capacity_blocked'))return 'capacity_blocked';if(codes.has('workpaper_missing'))return 'missing_workpaper';if(codes.size)return 'workpaper_incomplete';return 'matched_reviewed'}
