import {M76_DIESEL_PROFILE,M76_DIESEL_PERIOD,M76_DIESEL_FUEL,M76_DIESEL_LIMITATIONS,type M76DieselSaveInput,type M76DieselActivity,type M76DieselActivityStatus,type M76DieselReviewInput,type M76DieselReportInput,type M76DieselVersion,type M76DieselReview,type M76DieselReport,type M76DieselCalculation,type M76DieselStatementInput,type M76DieselEquipmentInput,type M76DieselBindingInput} from './m76-diesel-contract'
export const m76DieselCanonicalJson=m71CanonicalJson
export class M76DieselValidationError extends Error {}
export const m76DieselRequire=(v:unknown,message='Invalid synthetic stationary-generator request.'):void=>{if(!v)throw new M76DieselValidationError(message)}
export const m76DieselKeys=(v:unknown,keys:string[])=>{try{m71Keys(v,keys)}catch{throw new M76DieselValidationError('Unexpected or missing stationary-generator fields.')}}
export function m76DieselText(v:unknown,max=500):string{m76DieselRequire(typeof v==='string'&&v.length>0);const text=(v as string).trim().normalize('NFC');m76DieselRequire(text.length>0&&Array.from(text).length<=max&&!/[\u0000-\u001f\u007f-\u009f\ud800-\udfff]/u.test(text));return text}
export const m76DieselNullableText=(v:unknown,max=500)=>v===null?null:m76DieselText(v,max)
export function m76DieselQuantity(v:unknown):string{m76DieselRequire(typeof v==='string'&&/^(?:0|[1-9][0-9]{0,11})(?:\.[0-9]{1,3})?$/.test(v));const [whole,fraction='']=(v as string).split('.');return whole+'.'+fraction.padEnd(3,'0')}
export function m76EquipmentId(v:unknown):string{m76DieselRequire(typeof v==='string');const id=(v as string).trim().toUpperCase();m76DieselRequire(/^[A-Z0-9][A-Z0-9._-]{0,63}$/.test(id),'Equipment ID needs 1–64 ASCII letters, numbers, period, underscore or hyphen.');return id}
export function validateM76DieselEquipment(value:unknown):M76DieselEquipmentInput{m76DieselKeys(value,['assetId','identifierBasis','equipmentType','engineType','stationaryInstallation','controlBasis','controlExplanation','fuel','fossilFraction','fuelGradeBasis']);const e=structuredClone(value) as M76DieselEquipmentInput;m76DieselRequire(e.equipmentType==='stationary_emergency_generator'&&e.engineType==='compression_ignition'&&e.stationaryInstallation==='fixed'&&e.controlBasis==='owned_operational_control_full_year'&&e.fuel===M76_DIESEL_FUEL&&e.fossilFraction==='1.000');e.assetId=m76EquipmentId(e.assetId);e.identifierBasis=m76DieselText(e.identifierBasis);e.controlExplanation=m76DieselText(e.controlExplanation);e.fuelGradeBasis=m76DieselText(e.fuelGradeBasis);return e}
export function validateM76DieselStatement(value:unknown):M76DieselStatementInput{m76DieselKeys(value,['issuer','reference','meterLabel','statedQuantityGallons','description','consumptionBasis','measurementBasis','dedicatedToSingleDevice','includesTesting','stockDerivedConsumption','sharedFuelAllocation','consumptionBoundaryExplanation','supplierSpecificHhvAvailable','supplierSpecificCarbonAvailable','defaultFactorEligibilityExplanation']);const s=structuredClone(value) as M76DieselStatementInput;m76DieselRequire(s.consumptionBasis==='dedicated_generator_consumed_no_adjustments'&&s.measurementBasis==='direct_device_fuel_meter'&&s.dedicatedToSingleDevice===true&&s.includesTesting===true&&s.stockDerivedConsumption===false&&s.sharedFuelAllocation===false&&s.supplierSpecificHhvAvailable===false&&s.supplierSpecificCarbonAvailable===false);s.issuer=m76DieselText(s.issuer,120);s.reference=m76DieselText(s.reference,120);s.meterLabel=m76DieselText(s.meterLabel,120);s.description=m76DieselText(s.description,2000);s.statedQuantityGallons=m76DieselQuantity(s.statedQuantityGallons);s.consumptionBoundaryExplanation=m76DieselText(s.consumptionBoundaryExplanation,2000);s.defaultFactorEligibilityExplanation=m76DieselText(s.defaultFactorEligibilityExplanation,2000);return s}
export function validateM76DieselSave(value:unknown):M76DieselSaveInput{
 m76DieselKeys(value,['profile','binding','period','equipment','unit','quantityGallons','statement','manualConfirmation','discrepancyReason','zeroReason','expectedVersionId','expectedVersionSha256','correctionReason','idempotencyKey']);const v=structuredClone(value) as M76DieselSaveInput
 m76DieselKeys(v.binding,['coverageVersionId','coverageVersionSha256','entityId','facilityId','sourceId','boundaryDecisionId']);for(const [k,x]of Object.entries(v.binding))m76DieselRequire(k.endsWith('Sha256')?m71HashString(x):m71Uuid(x));m76DieselKeys(v.period,['start','endExclusive']);m76DieselRequire(v.profile===M76_DIESEL_PROFILE&&m76DieselCanonicalJson(v.period)===m76DieselCanonicalJson(M76_DIESEL_PERIOD)&&v.unit==='US_gallon'&&typeof v.manualConfirmation==='boolean'&&m71Uuid(v.idempotencyKey));v.equipment=validateM76DieselEquipment(v.equipment);v.quantityGallons=v.quantityGallons===null?null:m76DieselQuantity(v.quantityGallons);v.statement=v.statement===null?null:validateM76DieselStatement(v.statement);v.discrepancyReason=m76DieselNullableText(v.discrepancyReason);v.zeroReason=m76DieselNullableText(v.zeroReason);v.correctionReason=m76DieselNullableText(v.correctionReason)
 if(v.expectedVersionId===null)m76DieselRequire(v.expectedVersionSha256===null&&v.correctionReason===null);else m76DieselRequire(m71Uuid(v.expectedVersionId)&&m71HashString(v.expectedVersionSha256)&&v.correctionReason!==null)
 if(v.quantityGallons!==null&&v.statement&&v.quantityGallons!==v.statement.statedQuantityGallons)m76DieselRequire(v.discrepancyReason!==null,'Explain the unresolved entered-versus-stated consumption discrepancy.');return v
}
export function validateM76DieselReview(value:unknown):M76DieselReviewInput{m76DieselKeys(value,['versionId','expectedVersionSha256','decision','note','acknowledgedLimitations','idempotencyKey']);const v=structuredClone(value) as M76DieselReviewInput;m76DieselRequire(m71Uuid(v.versionId)&&m71HashString(v.expectedVersionSha256)&&m71Uuid(v.idempotencyKey)&&['accepted_bounded_internal','changes_requested'].includes(v.decision)&&m76DieselCanonicalJson(v.acknowledgedLimitations)===m76DieselCanonicalJson(M76_DIESEL_LIMITATIONS));v.note=m76DieselText(v.note);return v}
export function validateM76DieselReport(value:unknown):M76DieselReportInput{m76DieselKeys(value,['versionId','expectedVersionSha256','expectedDecisionId','expectedDecisionSha256','idempotencyKey']);const v=value as M76DieselReportInput;m76DieselRequire(m71Uuid(v.versionId)&&m71HashString(v.expectedVersionSha256)&&m71Uuid(v.idempotencyKey)&&(v.expectedDecisionId===null?v.expectedDecisionSha256===null:m71Uuid(v.expectedDecisionId)&&m71HashString(v.expectedDecisionSha256)));return structuredClone(v)}
export function m76DieselActivity(v:M76DieselSaveInput):M76DieselActivity{const {expectedVersionId:_,expectedVersionSha256:__,correctionReason:___,idempotencyKey:____,...activity}=v;return activity}
export function m76DieselCanCalculate(a:M76DieselActivity):boolean{return a.quantityGallons!==null&&a.statement!==null&&a.manualConfirmation&&(a.quantityGallons==='0.000'?a.statement.statedQuantityGallons==='0.000'&&Boolean(a.zeroReason):a.quantityGallons===a.statement.statedQuantityGallons||Boolean(a.discrepancyReason))}
export function deriveM76DieselActivityStatus(a:M76DieselActivity):M76DieselActivityStatus{return a.quantityGallons===null?'missing':a.statement===null?'evidence_missing':!a.manualConfirmation?'unconfirmed':a.quantityGallons!==a.statement.statedQuantityGallons?'discrepancy':a.quantityGallons==='0.000'?(m76DieselCanCalculate(a)?'explicit_zero':'unsupported_zero'):'entered'}
export function deriveM76DieselFindings(a:M76DieselActivity){const findings=[{code:'scope1_incomplete',message:'This generator subtotal does not cover all stationary, mobile, fugitive or process emissions.'},{code:'method_not_released',message:'Factors and method are development candidates; no reporting or assurance determination.'}];const status=deriveM76DieselActivityStatus(a);if(a.quantityGallons===null)findings.push({code:'activity_missing',message:'Consumed U.S. gallons are missing; no emissions were calculated.'});if(a.statement===null)findings.push({code:'statement_missing',message:'No synthetic consumed-fuel statement is retained.'});if(status==='unconfirmed')findings.push({code:'statement_unconfirmed',message:'The synthetic consumption evidence has not been manually confirmed.'});if(status==='discrepancy')findings.push({code:'activity_statement_discrepancy',message:'Entered and stated consumption differ; the discrepancy remains unresolved.'});if(a.quantityGallons==='0.000'&&!m76DieselCanCalculate(a))findings.push({code:'unsupported_zero',message:'Zero needs matching zero evidence and a no-consumption rationale covering test and maintenance runs.'});return findings}
export const m76DieselSourceChoices=m73SourceChoices
export function m76DieselResolveBinding(binding:M76DieselBindingInput,coverage:M71Version){try{return m73ResolveBinding(binding,coverage)}catch{throw new M76DieselValidationError('The selected saved stationary source or boundary is not eligible.')}}
export function m76DieselStatementText(a:M76DieselActivity,coverage:M71Version):string{m76DieselRequire(a.statement!==null);const choice=m76DieselResolveBinding(a.binding,coverage);return 'SYNTHETIC — NOT AN ORIGINAL FUEL RECORD OR INDEPENDENT MEASUREMENT\n'+m76DieselCanonicalJson({profile:'m76-synthetic-generator-statement-v1',companyLabel:choice.companyLabel,entityLabel:choice.entityLabel,facilityLabel:choice.facilityLabel,sourceLabel:choice.sourceLabel,binding:a.binding,period:a.period,equipment:a.equipment,unit:a.unit,statement:a.statement})+'\n'}
export const m76DieselInputHashPayload=(v:Pick<M76DieselVersion,'activity'>)=>v.activity
export const m76DieselContentPayload=(v:Pick<M76DieselVersion,'activity'|'activityStatus'|'coverageVersion'|'statement'|'calculation'|'findings'>)=>({activity:v.activity,activityStatus:v.activityStatus,coverageVersion:v.coverageVersion,statement:v.statement,calculation:v.calculation,findings:v.findings})
export const m76DieselVersionHashPayload=(v:M76DieselVersion)=>({profile:M76_DIESEL_PROFILE,id:v.id,companyId:v.companyId,worksheetId:v.worksheetId,version:v.version,previousVersionId:v.previousVersionId,previousVersionSha256:v.previousVersionSha256,createdBy:v.createdBy,createdAt:v.createdAt,contributorIds:v.contributorIds,correctionReason:v.correctionReason,inputSha256:v.inputSha256,contentSha256:v.contentSha256})
export function m76DieselReviewHashPayload(companyId:string,r:M76DieselReview){const {decisionSha256:_,...body}=r;return {profile:M76_DIESEL_PROFILE,companyId,...body}}
export function m76DieselReportHashPayload(r:M76DieselReport){const {reportSha256:_,html:__,snapshotJson:___,...body}=r;return {profile:M76_DIESEL_PROFILE,...body}}
export function m76DieselCalculationHashPayload(c:M76DieselCalculation){const {resultSha256:_,...body}=c;return body}
export const m76DieselExport=(v:M76DieselVersion)=>m76DieselCanonicalJson({...v,review:null})

import type {WorkspaceSql} from './workspace'
import {readCorporateInventory,m71Export} from './m71'
import {M76_DIESEL_PROFILE,M76_DIESEL_LIMITATIONS,M76_DIESEL_METHOD,type M76DieselAuthority,type M76DieselRegister,type M76DieselVersion,type M76DieselReview,type M76DieselReport,type M76DieselSaveInput,type M76DieselReviewInput,type M76DieselReportInput,type M76DieselCalculation} from './m76-diesel-contract'
import {m76DieselCanonicalJson,validateM76DieselSave,validateM76DieselReview,validateM76DieselReport,m76DieselActivity,m76DieselResolveBinding,m76DieselSourceChoices,m76DieselStatementText,m76DieselInputHashPayload,m76DieselContentPayload,m76DieselVersionHashPayload,m76DieselReviewHashPayload,m76DieselReportHashPayload,m76DieselCalculationHashPayload,m76DieselExport,deriveM76DieselFindings,m76DieselKeys,deriveM76DieselActivityStatus,m76DieselCanCalculate} from './m76-diesel-validation'
