 values_map:=values_map||jsonb_build_object('differences',coalesce((select string_agg(value,', ' order by ord) from jsonb_array_elements_text(coalesce(source#>'{coverage,quantityDifferenceMonths}','[]'::jsonb)) with ordinality t(value,ord)),'None'));
 values_map:=values_map||jsonb_build_object('acknowledgments',coalesce((select string_agg(value,', ' order by ord) from jsonb_array_elements_text(coalesce(source#>'{review,acknowledgedLimitations}','[]'::jsonb)) with ordinality t(value,ord)),'None'));
 values_map:=values_map||jsonb_build_object('d0difference',case when source#>'{links,0}' is null then 'No document linked.' when source#>>'{links,0,source,printedQuantityKwh}'=source#>>'{annual,months,0,quantityKwh}' then 'Printed and manual January quantities match; document and inputs remain unverified.' else 'Manual quantity differs from the fictional bill. Explanation recorded; difference remains.' end);
 values_map:=values_map||jsonb_build_object('d1difference',case when source#>'{links,1}' is null then 'No document linked.' when source#>>'{links,1,source,printedQuantityKwh}'=source#>>'{annual,months,0,quantityKwh}' then 'Printed and manual January quantities match; document and inputs remain unverified.' else 'Manual quantity differs from the fictional bill. Explanation recorded; difference remains.' end);
 for item in select key,value from jsonb_each_text(values_map) loop
  if item.value is null then raise exception 'invalid report source' using errcode='22023';end if;
  escaped:=replace(replace(replace(replace(replace(replace(replace(item.value,'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),'''','&#39;'),'{','&#123;'),'}','&#125;');
  result:=replace(result,'{{'||item.key||'}}',escaped);
 end loop;
 if result ~ '\{\{[a-zA-Z0-9]+\}\}' then raise exception 'unresolved report template';end if;
 return convert_to(result,'utf8');
end $$;
revoke all on function neuvetra.render_annual_evidence_report(uuid,uuid,uuid,text,jsonb,text) from public,authenticated;
create function neuvetra.create_annual_evidence_report(target_company uuid,request jsonb) returns uuid
language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
declare actor uuid:=neuvetra.current_user_id(); v record; r record; prior record; source jsonb; report_id uuid; fingerprint text;
 template_sha text:=encode(sha256(convert_to(neuvetra.annual_evidence_report_template(),'utf8')),'hex'); captured timestamptz; captured_text text; content bytea; content_sha text; meta jsonb;
begin
 if actor is null or not neuvetra.can_manage_company(target_company) then raise exception 'workspace not found' using errcode='42501';end if;
 perform id from neuvetra.companies where id=target_company for update;
 if not neuvetra.can_manage_company(target_company) then raise exception 'workspace not found' using errcode='42501';end if;
 if jsonb_typeof(request) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(request) key) is distinct from array['expectedInputSha256','expectedResultSha256','expectedReviewId','expectedReviewSha256','idempotencyKey','sourceVersionId']::text[] then raise exception 'invalid report request' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(request) where key not in('expectedReviewId','expectedReviewSha256') and jsonb_typeof(value)<>'string') or request->>'sourceVersionId' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'idempotencyKey' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'expectedInputSha256' !~ '^[0-9a-f]{64}$' or request->>'expectedResultSha256' !~ '^[0-9a-f]{64}$' then raise exception 'invalid report request' using errcode='22023';end if;
 if not ((request->'expectedReviewId'='null'::jsonb and request->'expectedReviewSha256'='null'::jsonb) or (jsonb_typeof(request->'expectedReviewId')='string' and jsonb_typeof(request->'expectedReviewSha256')='string' and request->>'expectedReviewId' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' and request->>'expectedReviewSha256' ~ '^[0-9a-f]{64}$')) then raise exception 'invalid review binding' using errcode='22023';end if;
 select * into v from neuvetra.annual_electricity_evidence_versions where company_id=target_company and id=(request->>'sourceVersionId')::uuid;
 if not found or v.input_sha256 is distinct from request->>'expectedInputSha256' or v.result_sha256 is distinct from request->>'expectedResultSha256' then raise exception 'report source conflicts' using errcode='23505';end if;
 fingerprint:=neuvetra.m67_hash(jsonb_build_object('profile','neuvetra.synthetic.annual-electricity-evidence-report.v1','companyId',target_company,'sourceVersionId',v.id,'inputSha256',v.input_sha256,'resultSha256',v.result_sha256,'reviewId',request->'expectedReviewId','reviewSha256',request->'expectedReviewSha256','templateVersion','m68-annual-evidence-report-v1','templateSha256',template_sha));
 select * into prior from neuvetra.annual_evidence_report_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;
 if found then
  if prior.operation_fingerprint<>fingerprint then raise exception 'report request conflicts' using errcode='23505';end if;
  return prior.report_id;
 end if;
 select id into report_id from neuvetra.annual_evidence_reports where company_id=target_company and operation_fingerprint=fingerprint;
 if found then
  insert into neuvetra.annual_evidence_report_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,report_id,actor);
  return report_id;
 end if;
 select * into r from neuvetra.annual_electricity_evidence_reviews where company_id=target_company and version_id=v.id;
 if r.id is distinct from (request->>'expectedReviewId')::uuid or r.decision_sha256 is distinct from request->>'expectedReviewSha256' then raise exception 'report review snapshot changed' using errcode='23505';end if;
 source:=v.payload||jsonb_build_object('createdAt',to_char(v.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'review',case when r.id is null then 'null'::jsonb else r.payload||jsonb_build_object('reviewedAt',to_char(r.reviewed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) end);
 report_id:=gen_random_uuid();captured:=date_trunc('milliseconds',clock_timestamp());captured_text:=to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 content:=neuvetra.render_annual_evidence_report(report_id,target_company,actor,captured_text,source,fingerprint);
 content_sha:=encode(sha256(content),'hex');
 insert into neuvetra.annual_evidence_reports values(report_id,target_company,v.id,v.input_sha256,v.result_sha256,r.id,r.decision_sha256,'m68-annual-evidence-report-v1',template_sha,source,content,content_sha,octet_length(content),fingerprint,actor,captured);
 insert into neuvetra.annual_evidence_report_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,report_id,actor);
 meta:=jsonb_build_object('profile','neuvetra.synthetic.annual-electricity-evidence-report.v1','reportId',report_id,'sourceVersionId',v.id,'inputSha256',v.input_sha256,'resultSha256',v.result_sha256,'reviewId',r.id,'reviewSha256',r.decision_sha256,'templateVersion','m68-annual-evidence-report-v1','templateSha256',template_sha,'reportSha256',content_sha,'reportByteLength',octet_length(content),'identitySha256',fingerprint);
 insert into neuvetra.annual_evidence_report_audit values(gen_random_uuid(),target_company,report_id,actor,meta,captured);
 return report_id;
end $$;
revoke all on function neuvetra.create_annual_evidence_report(uuid,jsonb) from public,authenticated;
do $$ begin
 if exists(select 1 from pg_roles where rolname='neuvetra_runtime') then
  grant execute on function neuvetra.lock_annual_evidence_report_read(uuid),neuvetra.create_annual_evidence_report(uuid,jsonb) to neuvetra_runtime;
  revoke all on function neuvetra.lock_annual_evidence_report_read(uuid) from authenticated;
 end if;
end $$;

-- M71: additive synthetic corporate coverage; historical migrations/rows untouched.
create table neuvetra.corporate_inventory_heads(company_id uuid primary key references neuvetra.companies(id),id uuid not null,version_id uuid,revision integer not null default 0,unique(id,company_id));
create table neuvetra.corporate_inventory_versions(id uuid primary key,company_id uuid not null,inventory_id uuid not null,version integer not null check(version>0),previous_version_id uuid,payload jsonb not null,content_sha256 text not null check(content_sha256~'^[0-9a-f]{64}$'),version_sha256 text not null check(version_sha256~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,version),foreign key(inventory_id,company_id) references neuvetra.corporate_inventory_heads(id,company_id),foreign key(previous_version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id));
alter table neuvetra.corporate_inventory_heads add foreign key(version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id);
create table neuvetra.corporate_inventory_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null check(decision_sha256~'^[0-9a-f]{64}$'),reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),unique(company_id,version_id),foreign key(version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id));
create table neuvetra.corporate_inventory_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,fingerprint text not null check(fingerprint~'^[0-9a-f]{64}$'),kind text not null check(kind in('save','review')),record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.corporate_inventory_audit(id uuid primary key,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review')),record_sha256 text not null check(record_sha256~'^[0-9a-f]{64}$'),actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));
do $$ declare relation text;begin foreach relation in array array['corporate_inventory_heads','corporate_inventory_versions','corporate_inventory_reviews','corporate_inventory_requests','corporate_inventory_audit'] loop
 execute format('alter table neuvetra.%I enable row level security',relation);execute format('alter table neuvetra.%I force row level security',relation);
 execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',relation);
 execute format('create policy m71_runtime_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.is_company_member(company_id))',relation);execute format('grant select on neuvetra.%I to neuvetra_runtime',relation);
 if relation<>'corporate_inventory_heads' then execute format('create trigger m71_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',relation);end if;
end loop;end $$;

-- Admission -> membership -> company/head. Revocation UPDATE waits for an admitted
-- operation, or completes first and causes the waiting operation to fail closed.
create function neuvetra.m71_lock(target_company uuid,manager boolean) returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
declare actor uuid:=auth.uid();a record;m record;begin
 select * into a from neuvetra.staging_access where user_id=actor for share;
 if not found or not a.active or a.company_id is distinct from target_company then return false;end if;
 select * into m from neuvetra.company_members where company_id=target_company and user_id=actor for share;
 if not found or (manager and m.role not in('owner','admin')) then return false;end if;
 return neuvetra.is_company_member(target_company) and (not manager or neuvetra.can_manage_company(target_company));end $$;

create function neuvetra.m71_keys(v jsonb,keys text) returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$ begin
 if jsonb_typeof(v) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(v) key) is distinct from (select array_agg(k order by k) from unnest(string_to_array(keys,',')) k) then raise exception 'invalid corporate object keys' using errcode='22023';end if;end $$;
create function neuvetra.m71_node(v jsonb,kind text) returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
declare spec text;pair record;child jsonb;childkind text;str text;arr jsonb;begin
 spec:=case kind
 when 'snapshot' then 'profile,companyLabel,period,consolidationApproach,policyVersion,entities,relationships,facilities,sources,boundaryDecisions,coverageItems,requirements'
 when 'period' then 'start,endExclusive'
 when 'entities' then 'id,legalName,countryCode,regionCode,start,endExclusive,evidenceRefs'
 when 'relationships' then 'id,parentEntityId,childEntityId,ownershipPercent,controlFacts,start,endExclusive,evidenceRefs'
 when 'facilities' then 'id,entityId,name,countryCode,regionCode,start,endExclusive,evidenceRefs'
 when 'sources' then 'id,entityId,facilityId,name,domain,start,endExclusive,evidenceRefs'
 when 'boundaryDecisions' then 'id,entityId,disposition,reason,start,endExclusive,evidenceRefs'
 when 'coverageItems' then 'id,domain,entityId,sourceId,disposition,activityDataState,evidenceState,methodReadiness,reason,evidenceRefs,estimateBasis,quantity,unit,start,endExclusive'
 when 'requirements' then 'id,character,sourceLocator,sourceEdition,lastCheckedOn,applicability,missingFacts,reason'
 when 'evidenceRefs' then 'artifactId,expectedSha256,locator,purpose'
 when 'estimateBasis' then 'methodVersionId,assumptions,inputEvidenceRefs,uncertainty' end;
 if spec is null then raise exception 'invalid corporate shape' using errcode='22023';end if;perform neuvetra.m71_keys(v,spec);
 for pair in select key,value from jsonb_each(v) loop
  if pair.key in('period','estimateBasis') then if pair.key='estimateBasis' and pair.value='null'::jsonb then continue;end if;perform neuvetra.m71_node(pair.value,pair.key);
  elsif pair.key in('entities','relationships','facilities','sources','boundaryDecisions','coverageItems','requirements','evidenceRefs','inputEvidenceRefs','missingFacts') then
   if jsonb_typeof(pair.value) is distinct from 'array' or jsonb_array_length(pair.value)>150 then raise exception 'invalid corporate array' using errcode='22023';end if;
   childkind:=case when pair.key='inputEvidenceRefs' then 'evidenceRefs' else pair.key end;
   if pair.key='missingFacts' then
    if jsonb_array_length(pair.value) not between 1 and 20 or exists(select 1 from jsonb_array_elements(pair.value) e where jsonb_typeof(e)<>'string' or length(e#>>'{}') not between 1 and 100 or e#>>'{}'<>btrim(e#>>'{}') or e#>>'{}'<>normalize(e#>>'{}',NFC) or e#>>'{}'~'[[:cntrl:]]') or (select count(distinct e) from jsonb_array_elements(pair.value)e)<>jsonb_array_length(pair.value) then raise exception 'invalid missing facts' using errcode='22023';end if;
    select jsonb_agg(e order by e#>>'{}' collate "C") into arr from jsonb_array_elements(pair.value)e;
   else
    for child in select value from jsonb_array_elements(pair.value) loop perform neuvetra.m71_node(child,childkind);end loop;
    if childkind='evidenceRefs' then
     if jsonb_array_length(pair.value)>8 or (select count(distinct e->>'purpose') from jsonb_array_elements(pair.value)e)<>jsonb_array_length(pair.value) then raise exception 'duplicate evidence purpose' using errcode='22023';end if;
     select coalesce(jsonb_agg(e order by e->>'purpose' collate "C"),'[]') into arr from jsonb_array_elements(pair.value)e;
    else select coalesce(jsonb_agg(e order by e->>'id' collate "C"),'[]') into arr from jsonb_array_elements(pair.value)e;end if;
   end if;
   if arr is distinct from pair.value then raise exception 'corporate arrays must be canonical' using errcode='22023';end if;
  else
   if pair.value='null'::jsonb and (pair.key in('regionCode','ownershipPercent','controlFacts','facilityId','reason','quantity','unit','sourceLocator','sourceEdition','lastCheckedOn') or kind='coverageItems' and pair.key in('entityId','sourceId')) then continue;end if;
   if jsonb_typeof(pair.value) is distinct from 'string' then raise exception 'invalid corporate scalar type' using errcode='22023';end if;
   str:=pair.value#>>'{}';
   if length(str) not between 1 and 500 or str<>btrim(str) or str<>normalize(str,NFC) or str~'[[:cntrl:]]' then raise exception 'invalid corporate text' using errcode='22023';end if;
   if pair.key in('companyLabel','legalName','name') and length(str)>160 or pair.key in('policyVersion','methodVersionId') and length(str)>100 or pair.key='unit' and length(str)>40 then raise exception 'corporate label too long' using errcode='22023';end if;
   if pair.key in('id','entityId','sourceId','facilityId','parentEntityId','childEntityId','artifactId') and str!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid corporate ID' using errcode='22023';end if;
   if pair.key in('start','endExclusive','lastCheckedOn') and (str!~'^\d{4}-\d{2}-\d{2}$' or to_char(str::date,'YYYY-MM-DD')<>str) then raise exception 'invalid corporate date' using errcode='22023';end if;
   if pair.key='countryCode' and str!~'^[A-Z]{2}$' or pair.key='regionCode' and str!~'^[A-Z0-9-]{1,12}$' then raise exception 'invalid corporate geography' using errcode='22023';end if;
   if pair.key in('quantity','ownershipPercent') and (str!~'^(0|[1-9][0-9]{0,17})(\.[0-9]{0,5}[1-9])?$' or (pair.key='ownershipPercent' and str::numeric>100)) then raise exception 'invalid corporate decimal' using errcode='22023';end if;
   if pair.key='disposition' and str not in('unassessed','missing','included_activity','included_estimate','excluded','not_applicable') or pair.key='activityDataState' and str not in('not_assessed','missing','partial','entered','estimate_proposed','explicit_zero') or pair.key='evidenceState' and str not in('not_assessed','missing','partial','linked','conflicting') or pair.key='methodReadiness' and str not in('not_assessed','unsupported','candidate') or pair.key='applicability' and str not in('unknown','conflicting') or pair.key='consolidationApproach' and str not in('operational_control','financial_control','equity_share') or pair.key='character' and str not in('statute','regulation','standard','agency_guidance','proposal','enforcement_statement','court_order') then raise exception 'invalid corporate state' using errcode='22023';end if;
  end if;
 end loop;
 if v ? 'start' and ((v->>'start')>=(v->>'endExclusive') or (v->>'start')<'2025-01-01' or (v->>'endExclusive')>'2026-01-01') then raise exception 'invalid corporate interval' using errcode='22023';end if;
 if kind='evidenceRefs' and (v->>'artifactId'<>'71000000-0000-4000-8000-000000000900' or v->>'expectedSha256'<>'4fe7dc12d8f253f8d3cb1fd7fba2eade05f3d605ad7cb95376cca9d957afe5c7' or v->>'locator'<>'synthetic-register:entities-and-screening') then raise exception 'unsupported synthetic evidence' using errcode='22023';end if;
 if v->>'disposition' in('excluded','not_applicable') and (v->'reason'='null'::jsonb or jsonb_array_length(v->'evidenceRefs')=0) then raise exception 'explanation and evidence required' using errcode='22023';end if;
end $$;

create function neuvetra.m71_snapshot(s jsonb,prior jsonb) returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
declare key text;row jsonb;other jsonb;parent jsonb;domain text;cursor text;ids text[]:='{}';domains text[]:=array['stationary_combustion','mobile_combustion','process','fugitive','electricity','steam','heat','cooling','location_based','market_based'];begin
 perform neuvetra.m71_node(s,'snapshot');
 if octet_length(convert_to(neuvetra.m67_canonical(s),'utf8'))>50000 or s->>'profile'<>'synthetic-corporate-coverage-v1' or s->'period'<>'{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or jsonb_array_length(s->'requirements')=0 then raise exception 'unsupported corporate profile' using errcode='22023';end if;
 if not exists(select 1 from jsonb_array_elements(s->'relationships')e where e->>'id'='71000000-0000-4000-8000-000000000010') then raise exception 'expected control relationship omitted' using errcode='22023';end if;
 for i in 1..15 loop domains:=array_append(domains,'scope3_'||i::text);end loop;
 foreach key in array array['entities','relationships','facilities','sources','boundaryDecisions','coverageItems','requirements'] loop
  for row in select value from jsonb_array_elements(s->key) loop
   if row->>'id'=any(ids) then raise exception 'duplicate corporate identity' using errcode='22023';end if;ids:=array_append(ids,row->>'id');
   if row ? 'domain' and not(row->>'domain'=any(domains)) then raise exception 'unknown screening domain' using errcode='22023';end if;
   if key in('facilities','sources','boundaryDecisions','coverageItems') and row->'entityId'<>'null'::jsonb then
    select e into parent from jsonb_array_elements(s->'entities')e where e->>'id'=row->>'entityId';
    if parent is null or row->>'start'<parent->>'start' or row->>'endExclusive'>parent->>'endExclusive' then raise exception 'invalid corporate entity binding' using errcode='22023';end if;
   end if;
  end loop;
  if prior is not null then for row in select value from jsonb_array_elements(prior->key) loop
   select e into other from jsonb_array_elements(s->key)e where e->>'id'=row->>'id';if other is null then raise exception 'corporate history cannot be omitted' using errcode='22023';end if;
   if (select jsonb_object_agg(k,v) from jsonb_each(row)t(k,v) where k in('entityId','sourceId','facilityId','parentEntityId','childEntityId','domain')) is distinct from (select jsonb_object_agg(k,v) from jsonb_each(other)t(k,v) where k in('entityId','sourceId','facilityId','parentEntityId','childEntityId','domain')) then raise exception 'corporate identity cannot be repurposed' using errcode='22023';end if;
  end loop;end if;
 end loop;
 foreach key in array array['entities','facilities','sources'] loop
  for i in 0..1 loop
   if not exists(select 1 from jsonb_array_elements(s->key)e where e->>'id'='71000000-0000-4000-8000-'||lpad((case key when 'entities' then 1 when 'facilities' then 20 else 30 end+i)::text,12,'0')) then raise exception 'expected corporate universe omitted' using errcode='22023';end if;
  end loop;
 end loop;
 for row in select value from jsonb_array_elements(s->'entities') loop
  cursor:=row->>'start';for other in select e from jsonb_array_elements(s->'boundaryDecisions')e where e->>'entityId'=row->>'id' order by e->>'start' loop
   if other->>'start'<>cursor then raise exception 'boundary interval gap or overlap' using errcode='22023';end if;cursor:=other->>'endExclusive';end loop;
  if cursor<>row->>'endExclusive' then raise exception 'missing boundary decision' using errcode='22023';end if;
 end loop;
 for row in select value from jsonb_array_elements(s->'relationships') loop
  foreach key in array array['parentEntityId','childEntityId'] loop select e into parent from jsonb_array_elements(s->'entities')e where e->>'id'=row->>key;
   if parent is null or row->>'start'<parent->>'start' or row->>'endExclusive'>parent->>'endExclusive' then raise exception 'invalid relationship binding' using errcode='22023';end if;end loop;
  if row->>'parentEntityId'=row->>'childEntityId' or exists(select 1 from jsonb_array_elements(s->'relationships')e where e->>'id'<>row->>'id' and e->>'childEntityId'=row->>'childEntityId' and e->>'start'<row->>'endExclusive' and row->>'start'<e->>'endExclusive') then raise exception 'overlapping relationship' using errcode='22023';end if;
 end loop;
 if exists(with recursive edges as(select e->>'parentEntityId' p,e->>'childEntityId' c,e->>'start' a,e->>'endExclusive' b from jsonb_array_elements(s->'relationships')e),walk as(select p,c,a,b,array[p,c] path,p=c cycle from edges union all select w.p,e.c,greatest(w.a,e.a),least(w.b,e.b),w.path||e.c,e.c=any(w.path) from walk w join edges e on e.p=w.c and e.a<w.b and w.a<e.b where not w.cycle)select 1 from walk where cycle) then raise exception 'effective relationship cycle' using errcode='22023';end if;
 for row in select value from jsonb_array_elements(s->'sources') loop
  if row->'facilityId'<>'null'::jsonb then select e into parent from jsonb_array_elements(s->'facilities')e where e->>'id'=row->>'facilityId';if parent is null or parent->>'entityId'<>row->>'entityId' or row->>'start'<parent->>'start' or row->>'endExclusive'>parent->>'endExclusive' then raise exception 'invalid source facility' using errcode='22023';end if;end if;
  if (select count(*) from jsonb_array_elements(s->'coverageItems')e where e->>'sourceId'=row->>'id' and e->>'start'=row->>'start' and e->>'endExclusive'=row->>'endExclusive')<>1 then raise exception 'source coverage missing' using errcode='22023';end if;
 end loop;
 for row in select value from jsonb_array_elements(s->'coverageItems') loop
  if row->'sourceId'<>'null'::jsonb then select e into parent from jsonb_array_elements(s->'sources')e where e->>'id'=row->>'sourceId';if parent is null or parent->>'entityId' is distinct from row->>'entityId' or parent->>'domain'<>row->>'domain' or row->>'start'<>parent->>'start' or row->>'endExclusive'<>parent->>'endExclusive' then raise exception 'invalid source screening' using errcode='22023';end if;
  elsif row->'entityId'<>'null'::jsonb then raise exception 'unsupported entity-only screening' using errcode='22023';
  elsif row->>'start'<>'2025-01-01' or row->>'endExclusive'<>'2026-01-01' then raise exception 'group screening must cover full period' using errcode='22023';end if;
  if (row->'quantity'='null'::jsonb)<>(row->'unit'='null'::jsonb) or (coalesce(row->>'quantity'='0',false))<>(row->>'activityDataState'='explicit_zero') or (row->'quantity'<>'null'::jsonb and row->>'activityDataState' not in('entered','partial','estimate_proposed','explicit_zero')) then raise exception 'invalid activity state' using errcode='22023';end if;
  if row->>'evidenceState'='linked' and jsonb_array_length(row->'evidenceRefs')=0 or row->>'activityDataState'='explicit_zero' and (row->'reason'='null'::jsonb or jsonb_array_length(row->'evidenceRefs')=0) then raise exception 'activity evidence missing' using errcode='22023';end if;
  if row->>'disposition'='included_estimate' and (row->'estimateBasis'='null'::jsonb or row->>'activityDataState'<>'estimate_proposed') or row->'estimateBasis'<>'null'::jsonb and jsonb_array_length(row#>'{estimateBasis,inputEvidenceRefs}')=0 then raise exception 'invalid estimate basis' using errcode='22023';end if;
 end loop;
 foreach domain in array domains loop if (select count(*) from jsonb_array_elements(s->'coverageItems')e where e->'entityId'='null'::jsonb and e->'sourceId'='null'::jsonb and e->>'domain'=domain and e->>'start'='2025-01-01' and e->>'endExclusive'='2026-01-01')<>1 then raise exception 'required group screening missing or duplicated' using errcode='22023';end if;end loop;
end $$;

-- Frozen coverage-only export findings. TypeScript independently derives these on read.
create function neuvetra.m71_findings(s jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
declare result jsonb:='[]';r jsonb;code text;begin
 result:=jsonb_build_array(jsonb_build_object('code','requirements_not_determined','recordId',null,'message','Corporate applicability and reporting requirements remain undetermined.'),jsonb_build_object('code','methods_not_released','recordId',null,'message','No corporate calculation method is released; emissions remain unknown.'));
 if s->>'consolidationApproach'<>'operational_control' then result:=result||jsonb_build_array(jsonb_build_object('code','unsupported_consolidation','recordId',null,'message','This consolidation approach requires a later reviewed method.'));end if;
 for r in select e from jsonb_array_elements((s->'entities')||(s->'facilities'))e loop
  if r->>'countryCode'<>'US' or r->>'regionCode' is distinct from 'CA' then result:=result||jsonb_build_array(jsonb_build_object('code','unsupported_geography','recordId',r->'id','message','Discovered operations remain registered; this milestone supports only California operations.'));end if;
  if r->>'start'<>'2025-01-01' or r->>'endExclusive'<>'2026-01-01' then result:=result||jsonb_build_array(jsonb_build_object('code','unsupported_temporal_allocation','recordId',r->'id','message','Partial-year control/operations need reviewed interval allocation.'));end if;
 end loop;
 for r in select e from jsonb_array_elements(s->'relationships')e loop
  if r->>'start'<>'2025-01-01' or r->>'endExclusive'<>'2026-01-01' or r->>'ownershipPercent' is distinct from '100' then result:=result||jsonb_build_array(jsonb_build_object('code','unsupported_boundary_relationship','recordId',r->'id','message','Partial-year or non-wholly-owned relationships need reviewed allocation.'));end if;
  if r->'controlFacts'='null'::jsonb or jsonb_array_length(r->'evidenceRefs')=0 then result:=result||jsonb_build_array(jsonb_build_object('code','control_evidence_missing','recordId',r->'id','message','Control facts and supporting evidence are incomplete.'));end if;
 end loop;
 for r in select e from jsonb_array_elements(s->'boundaryDecisions')e loop
  if r->>'disposition' in('missing','unassessed') then result:=result||jsonb_build_array(jsonb_build_object('code','boundary_unreconciled','recordId',r->'id','message','Expected entity remains unreconciled.'));end if;
  if r->>'disposition' in('excluded','not_applicable') then result:=result||jsonb_build_array(jsonb_build_object('code','boundary_assertion_unverified','recordId',r->'id','message','Boundary exclusion/non-applicability remains visible and requires qualified review.'));end if;
 end loop;
 for r in select e from jsonb_array_elements(s->'coverageItems')e loop
  if r->'quantity'='null'::jsonb then result:=result||jsonb_build_array(jsonb_build_object('code','activity_unknown','recordId',r->'id','message','No activity quantity is recorded; unknown is not zero.'));end if;
  if r->>'evidenceState'<>'linked' then code:=case when r->>'evidenceState'='conflicting' then 'evidence_conflicting' else 'evidence_incomplete' end;result:=result||jsonb_build_array(jsonb_build_object('code',code,'recordId',r->'id','message','Supporting evidence is missing, incomplete or conflicting.'));end if;
  if jsonb_array_length(r->'evidenceRefs')>0 then result:=result||jsonb_build_array(jsonb_build_object('code','synthetic_evidence_not_sufficient','recordId',r->'id','message','Pinned fictional evidence is not proof of activity or reporting sufficiency.'));end if;
  if r->>'methodReadiness'<>'candidate' then result:=result||jsonb_build_array(jsonb_build_object('code','method_unsupported','recordId',r->'id','message','This screening has no released calculation method.'));end if;
  if r->>'disposition' in('excluded','not_applicable') then result:=result||jsonb_build_array(jsonb_build_object('code','screening_assertion_unverified','recordId',r->'id','message','The assertion remains an open coverage finding.'));end if;
  if r->'estimateBasis'<>'null'::jsonb then result:=result||jsonb_build_array(jsonb_build_object('code','estimate_unverified','recordId',r->'id','message','Proposed estimate needs a reviewed method and supporting activity.'));end if;
 end loop;
 for r in select e from jsonb_array_elements(s->'requirements')e loop code:=case when r->>'applicability'='conflicting' then 'requirement_conflicting' else 'requirement_unknown' end;result:=result||jsonb_build_array(jsonb_build_object('code',code,'recordId',r->'id','message','Missing facts/source review prevent a legal determination.'));end loop;
 return (select jsonb_agg(e order by coalesce(e->>'recordId','') collate "C",e->>'code' collate "C") from jsonb_array_elements(result)e);
end $$;
revoke all on function neuvetra.m71_findings(jsonb) from public,authenticated,neuvetra_runtime;

create function neuvetra.save_corporate_inventory(target_company uuid,target_inventory uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
declare actor uuid:=auth.uid();head record;prior record;old record;body jsonb;s jsonb;fingerprint text;digest text;content_hash text;new_id uuid:=gen_random_uuid();captured timestamptz:=date_trunc('milliseconds',clock_timestamp());contributors jsonb;frozen_export text;begin
 if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;
 perform id from neuvetra.companies where id=target_company for update;
 perform neuvetra.m71_keys(request,'snapshot,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey');
 if request->>'idempotencyKey' is null or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid request key' using errcode='22023';end if;
 s:=request->'snapshot';perform neuvetra.m71_snapshot(s,null);
 fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save','actor',actor,'companyId',target_company,'inventoryId',target_inventory,'request',request-'idempotencyKey'));
 select * into old from neuvetra.corporate_inventory_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;
 if found then if old.fingerprint<>fingerprint or old.kind<>'save' then raise exception 'request conflict' using errcode='23505';end if;return old.record_id;end if;
 select * into head from neuvetra.corporate_inventory_heads where company_id=target_company for update;
 select * into prior from neuvetra.corporate_inventory_versions where company_id=target_company and id=head.version_id;
 if target_inventory is null then
  if head.id is not null then raise exception 'inventory exists' using errcode='23505';end if;
  if request->'expectedVersionId'<>'null'::jsonb or request->'expectedVersionSha256'<>'null'::jsonb or request->'correctionReason'<>'null'::jsonb then raise exception 'invalid initial binding' using errcode='22023';end if;
  insert into neuvetra.corporate_inventory_heads(company_id,id) values(target_company,gen_random_uuid()) returning * into head;
 else
  if head.id is null or head.id<>target_inventory then raise exception 'inventory conflict' using errcode='23505';end if;
  select * into prior from neuvetra.corporate_inventory_versions where company_id=target_company and id=head.version_id;
  if prior.id::text is distinct from request->>'expectedVersionId' or prior.version_sha256 is distinct from request->>'expectedVersionSha256' then raise exception 'stale corporate head' using errcode='23505';end if;
  if jsonb_typeof(request->'correctionReason')<>'string' or length(request->>'correctionReason') not between 1 and 500 or request->>'correctionReason'<>btrim(request->>'correctionReason') or request->>'correctionReason'<>normalize(request->>'correctionReason',NFC) or request->>'correctionReason'~'[[:cntrl:]]' then raise exception 'correction reason required' using errcode='22023';end if;
  perform neuvetra.m71_snapshot(s,prior.payload->'snapshot');if s=prior.payload->'snapshot' and request->'correctionReason'=prior.payload->'correctionReason' then raise exception 'corporate correction is no-op' using errcode='22023';end if;
 end if;
 if head.revision>=40 then raise exception 'synthetic history limit reached' using errcode='54000';end if;
 captured:=date_trunc('milliseconds',clock_timestamp());
 content_hash:=neuvetra.m67_hash(s);
 select jsonb_agg(e order by e collate "C") into contributors from (select distinct e from (select jsonb_array_elements_text(coalesce(prior.payload->'contributorIds','[]')) e union all select actor::text)e)e;
 body:=jsonb_build_object('profile','synthetic-corporate-coverage-v1','id',new_id,'inventoryId',head.id,'companyId',target_company,'version',head.revision+1,'previousVersionId',prior.id,'previousVersionSha256',prior.version_sha256,'createdBy',actor,'createdAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'contributorIds',contributors,'correctionReason',request->'correctionReason','contentSha256',content_hash);
 digest:=neuvetra.m67_hash(body);body:=(body-'profile')||jsonb_build_object('snapshot',s,'versionSha256',digest);
 frozen_export:=neuvetra.m67_canonical(body||jsonb_build_object('findings',neuvetra.m71_findings(s),'synthetic',true,'corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null,'review',null));
 -- Reserve 200 KB of the 4 MB reader budget for forty review records and envelope.
 if octet_length(convert_to(frozen_export,'utf8'))+coalesce((select sum(octet_length(convert_to(export_text,'utf8'))) from neuvetra.corporate_inventory_versions where company_id=target_company),0)>3800000 then raise exception 'synthetic history byte capacity reached' using errcode='54001';end if;
 insert into neuvetra.corporate_inventory_versions values(new_id,target_company,head.id,head.revision+1,prior.id,body,content_hash,digest,actor,captured,frozen_export);
 insert into neuvetra.corporate_inventory_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,'save',new_id);
 insert into neuvetra.corporate_inventory_audit values(gen_random_uuid(),target_company,new_id,'save',digest,actor,captured);
 update neuvetra.corporate_inventory_heads set version_id=new_id,revision=revision+1 where company_id=target_company;return new_id;
end $$;
create function neuvetra.review_corporate_inventory(target_company uuid,target_inventory uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
declare actor uuid:=auth.uid();v record;old record;body jsonb;fingerprint text;digest text;new_id uuid:=gen_random_uuid();captured timestamptz:=date_trunc('milliseconds',clock_timestamp());begin
 if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;
 perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,decision,note,acknowledgedLimitations,idempotencyKey');
 if exists(select 1 from jsonb_each(request) where key<>'acknowledgedLimitations' and jsonb_typeof(value)<>'string') or request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or request->>'note'<>normalize(request->>'note',NFC) or request->>'note'~'[[:cntrl:]]' then raise exception 'invalid review types' using errcode='22023';end if;
 if jsonb_typeof(request->'note')<>'string' or length(request->>'note') not between 1 and 500 or request->>'note'<>btrim(request->>'note') or request->>'decision' not in('accepted_bounded_internal','changes_requested') or request->'acknowledgedLimitations'<>'["synthetic_only","corporate_inventory_incomplete","methods_not_released","requirements_not_determined","no_emissions_calculated","no_external_assurance"]'::jsonb then raise exception 'invalid review' using errcode='22023';end if;
 fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','review','actor',actor,'companyId',target_company,'inventoryId',target_inventory,'request',request-'idempotencyKey'));
 select * into old from neuvetra.corporate_inventory_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;
 if found then if old.fingerprint<>fingerprint or old.kind<>'review' then raise exception 'request conflict' using errcode='23505';end if;return old.record_id;end if;
 select * into v from neuvetra.corporate_inventory_versions where company_id=target_company and inventory_id=target_inventory and id=(request->>'versionId')::uuid;
 if not found or v.version_sha256 is distinct from request->>'expectedVersionSha256' or v.payload->'contributorIds' ? actor::text or not exists(select 1 from neuvetra.corporate_inventory_heads where company_id=target_company and id=target_inventory and version_id=v.id) then raise exception 'review conflicts or contributor cannot review' using errcode='23505';end if;
 captured:=date_trunc('milliseconds',clock_timestamp());
 body:=jsonb_build_object('id',new_id,'versionId',v.id,'versionSha256',v.version_sha256,'decision',request->'decision','note',request->'note','acknowledgedLimitations',request->'acknowledgedLimitations','reviewerId',actor,'reviewedAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 digest:=neuvetra.m67_hash(body||jsonb_build_object('profile','synthetic-corporate-coverage-v1','companyId',target_company));body:=body||jsonb_build_object('decisionSha256',digest);
 insert into neuvetra.corporate_inventory_reviews values(new_id,target_company,v.id,body,digest,actor,captured);
 insert into neuvetra.corporate_inventory_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,'review',new_id);
 insert into neuvetra.corporate_inventory_audit values(gen_random_uuid(),target_company,new_id,'review',digest,actor,captured);return new_id;
end $$;
revoke all on function neuvetra.m71_keys(jsonb,text),neuvetra.m71_node(jsonb,text),neuvetra.m71_snapshot(jsonb,jsonb),neuvetra.m71_lock(uuid,boolean),neuvetra.save_corporate_inventory(uuid,uuid,jsonb),neuvetra.review_corporate_inventory(uuid,uuid,jsonb) from public,authenticated,neuvetra_runtime;
grant execute on function neuvetra.m71_lock(uuid,boolean),neuvetra.save_corporate_inventory(uuid,uuid,jsonb),neuvetra.review_corporate_inventory(uuid,uuid,jsonb) to neuvetra_runtime;

-- M73 additive source-scoped synthetic natural-gas workpapers. M42/M71 remain intact.
create table neuvetra.stationary_gas_heads(id uuid primary key,company_id uuid not null references neuvetra.companies(id),source_id uuid not null,version_id uuid,revision integer not null default 0,meter_key text,reference_key text,unique(id,company_id),unique(company_id,source_id),unique(company_id,meter_key),unique(company_id,reference_key));
create table neuvetra.stationary_gas_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.stationary_gas_versions(id uuid primary key,company_id uuid not null,worksheet_id uuid not null,version integer not null,previous_version_id uuid,coverage_version_id uuid not null,statement_id uuid,quantity_mmbtu numeric(15,3),payload jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,worksheet_id,version),foreign key(worksheet_id,company_id) references neuvetra.stationary_gas_heads(id,company_id),foreign key(previous_version_id,company_id) references neuvetra.stationary_gas_versions(id,company_id),foreign key(coverage_version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id),foreign key(statement_id,company_id) references neuvetra.stationary_gas_statements(id,company_id));
alter table neuvetra.stationary_gas_heads add foreign key(version_id,company_id) references neuvetra.stationary_gas_versions(id,company_id);
create table neuvetra.stationary_gas_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),unique(company_id,version_id),foreign key(version_id,company_id) references neuvetra.stationary_gas_versions(id,company_id));
create table neuvetra.stationary_gas_reports(id uuid primary key,company_id uuid not null,worksheet_id uuid not null,version_id uuid not null,decision_id uuid,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(worksheet_id,company_id) references neuvetra.stationary_gas_heads(id,company_id),foreign key(version_id,company_id) references neuvetra.stationary_gas_versions(id,company_id),foreign key(decision_id,company_id) references neuvetra.stationary_gas_reviews(id,company_id));
create unique index m73_report_state on neuvetra.stationary_gas_reports(company_id,version_id,coalesce(decision_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table neuvetra.stationary_gas_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.stationary_gas_audit(id uuid primary key,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review','report')),record_sha256 text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));
do $$declare t text;begin foreach t in array array['stationary_gas_heads','stationary_gas_statements','stationary_gas_versions','stationary_gas_reviews','stationary_gas_reports','stationary_gas_requests','stationary_gas_audit'] loop
execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m73_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);
if t<>'stationary_gas_heads' then execute format('create trigger m73_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;
create function neuvetra.m73_text(v jsonb,maximum integer) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s text:=v#>>'{}';begin if jsonb_typeof(v) is distinct from 'string' or length(s) not between 1 and maximum or s<>btrim(s) or s~U&'^[\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]|[\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]$' or s<>normalize(s,NFC) or s~'[[:cntrl:]]' then raise exception 'invalid text' using errcode='22023';end if;return s;end $$;
create function neuvetra.m73_quantity(v jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s text:=v#>>'{}';begin if jsonb_typeof(v) is distinct from 'string' or s!~'^(0|[1-9][0-9]{0,11})\.[0-9]{3}$' then raise exception 'invalid quantity' using errcode='22023';end if;return s;end $$;
create function neuvetra.m73_exact(v numeric) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case when position('.' in v::text)>0 then rtrim(rtrim(v::text,'0'),'.') else v::text end$$;
create function neuvetra.m73_display(v numeric) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$with x as(select v*10000 n),r as(select trunc(n) q,n-trunc(n) f from x) select to_char((q+case when f>0.5 or(f=0.5 and mod(q,2)=1)then 1 else 0 end)/10000,'FM999999999999999999999990.0000') from r$$;
create function neuvetra.m73_findings(a jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare out jsonb:='[{"code":"scope1_incomplete","message":"This source subtotal does not cover all stationary, mobile, fugitive or process emissions."},{"code":"method_not_released","message":"Factors and method are development candidates; no reporting or assurance determination."}]';begin
if a->'quantityMmbtu'='null' then out:=out||'[{"code":"activity_missing","message":"Activity is missing; no emissions were calculated."}]';end if;if a->'statement'='null' then out:=out||'[{"code":"statement_missing","message":"No synthetic activity statement is retained."}]';end if;if a->'quantityMmbtu'<>'null' and a->'statement'<>'null' and a->>'quantityMmbtu'<>a#>>'{statement,statedQuantityMmbtu}' then out:=out||'[{"code":"activity_statement_discrepancy","message":"Entered and stated quantities differ; the discrepancy remains unresolved."}]';end if;return out;end $$;
create function neuvetra.m73_coverage(target_company uuid,b jsonb,current_required boolean default true) returns jsonb language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare cv record;s jsonb;e jsonb;f jsonb;src jsonb;bd jsonb;rel jsonb;node text;seen text[]:='{}';pair record;begin
perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,entityId,facilityId,sourceId,boundaryDecisionId');for pair in select key,value from jsonb_each(b) loop if jsonb_typeof(pair.value)<>'string' or (pair.value#>>'{}') !~ (case when pair.key='coverageVersionSha256' then '^[0-9a-f]{64}$' else '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' end) then raise exception 'invalid binding' using errcode='22023';end if;end loop;
select * into cv from neuvetra.corporate_inventory_versions where company_id=target_company and id=(b->>'coverageVersionId')::uuid;if not found or cv.version_sha256<>b->>'coverageVersionSha256' then raise exception 'coverage binding conflict' using errcode='23505';end if;
if current_required and not exists(select 1 from neuvetra.corporate_inventory_heads where company_id=target_company and version_id=cv.id) then raise exception 'coverage changed' using errcode='23505';end if;
s:=cv.payload->'snapshot';perform neuvetra.m71_snapshot(s,null);if neuvetra.m67_hash(s)<>cv.content_sha256 or neuvetra.m67_hash((cv.payload-'snapshot'-'versionSha256')||jsonb_build_object('profile','synthetic-corporate-coverage-v1'))<>cv.version_sha256 or cv.export_text<>neuvetra.m67_canonical(cv.payload||jsonb_build_object('findings',neuvetra.m71_findings(s),'synthetic',true,'corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null,'review',null)) then raise exception 'coverage integrity failure' using errcode='22023';end if;
select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=b->>'entityId';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=b->>'facilityId';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=b->>'sourceId';select x into bd from jsonb_array_elements(s->'boundaryDecisions')x where x->>'id'=b->>'boundaryDecisionId';
if s->>'consolidationApproach'<>'operational_control' or e is null or f is null or src is null or bd is null or src->>'domain'<>'stationary_combustion' or src->>'entityId'<>e->>'id' or src->>'facilityId'<>f->>'id' or f->>'entityId'<>e->>'id' or bd->>'entityId'<>e->>'id' or e->>'countryCode'<>'US' or e->>'regionCode' is distinct from 'CA' or f->>'countryCode'<>'US' or f->>'regionCode' is distinct from 'CA' or bd->>'disposition'<>'included_activity' or bd->'reason'='null' or jsonb_array_length(bd->'evidenceRefs')=0 then raise exception 'source ineligible' using errcode='22023';end if;
for pair in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if pair.value->>'start'<>'2025-01-01' or pair.value->>'endExclusive'<>'2026-01-01' then raise exception 'unsupported period' using errcode='22023';end if;end loop;
node:=e->>'id';loop if node=any(seen) then raise exception 'relationship cycle' using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements(s->'relationships')x where x->>'childEntityId'=node;exit when rel is null;if rel->>'start'<>'2025-01-01' or rel->>'endExclusive'<>'2026-01-01' or rel->>'ownershipPercent' is distinct from '100' or rel->'controlFacts'='null' or jsonb_array_length(rel->'evidenceRefs')=0 then raise exception 'control basis incomplete' using errcode='22023';end if;node:=rel->>'parentEntityId';end loop;
return cv.export_text::jsonb;end $$;
create function neuvetra.m73_validate_request(r jsonb) returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare a jsonb;rkey text;begin
perform neuvetra.m71_keys(r,'profile,binding,period,fuel,heatBasis,unit,quantityMmbtu,statement,manualConfirmation,discrepancyReason,zeroReason,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey');
if r->>'profile' is distinct from 'synthetic-stationary-natural-gas-v1' or r->'period' is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or r->>'fuel' is distinct from 'Natural Gas' or r->>'heatBasis' is distinct from 'HHV' or r->>'unit' is distinct from 'MMBtu' or jsonb_typeof(r->'manualConfirmation') is distinct from 'boolean' or jsonb_typeof(r->'idempotencyKey') is distinct from 'string' or r->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid profile' using errcode='22023';end if;
foreach rkey in array array['discrepancyReason','zeroReason','correctionReason']loop if r->rkey<>'null' then perform neuvetra.m73_text(r->rkey,500);end if;end loop;
if r->'expectedVersionId'='null' then if r->'expectedVersionSha256'<>'null' or r->'correctionReason'<>'null' then raise exception 'initial binding invalid' using errcode='22023';end if;else if jsonb_typeof(r->'expectedVersionId')<>'string' or r->>'expectedVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(r->'expectedVersionSha256')<>'string' or r->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or r->'correctionReason'='null' then raise exception 'correction binding invalid' using errcode='22023';end if;end if;
if r->'statement'<>'null' then a:=r->'statement';perform neuvetra.m71_keys(a,'issuer,reference,meterLabel,statedQuantityMmbtu,description,consumptionBasis');perform neuvetra.m73_text(a->'issuer',120);perform neuvetra.m73_text(a->'reference',120);perform neuvetra.m73_text(a->'meterLabel',120);perform neuvetra.m73_text(a->'description',2000);perform neuvetra.m73_quantity(a->'statedQuantityMmbtu');if a->>'consumptionBasis' is distinct from 'dedicated_meter_consumed_no_adjustments' then raise exception 'consumption basis invalid' using errcode='22023';end if;end if;
if r->'quantityMmbtu'<>'null' then perform neuvetra.m73_quantity(r->'quantityMmbtu');if r->'statement'='null' or r->'manualConfirmation'<>'true' then raise exception 'evidence missing' using errcode='22023';end if;if r->>'quantityMmbtu'='0.000' then if r#>>'{statement,statedQuantityMmbtu}'<>'0.000' or r->'zeroReason'='null' then raise exception 'zero unsupported' using errcode='22023';end if;elsif r->>'quantityMmbtu'<>r#>>'{statement,statedQuantityMmbtu}' and r->'discrepancyReason'='null' then raise exception 'discrepancy reason missing' using errcode='22023';end if;end if;end $$;
create function neuvetra.m73_statement(a jsonb,coverage jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s jsonb:=coverage->'snapshot';e jsonb;f jsonb;src jsonb;begin select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=a#>>'{binding,entityId}';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=a#>>'{binding,facilityId}';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=a#>>'{binding,sourceId}';return 'SYNTHETIC — NOT A UTILITY BILL'||chr(10)||neuvetra.m67_canonical(jsonb_build_object('profile','m73-synthetic-gas-statement-v1','companyLabel',s->'companyLabel','entityLabel',e->'legalName','facilityLabel',f->'name','sourceLabel',src->'name','binding',a->'binding','period',a->'period','fuel',a->'fuel','heatBasis',a->'heatBasis','unit',a->'unit','statement',a->'statement'))||chr(10);end $$;

create function neuvetra.m73_method() returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '{"id":"stationary-natural-gas-combustion","version":"m73-development-v1","engineSha256":"e1b91d4fa6afa1126eeb642769c458d0b0b747c12ad5ee172543afb9246eaa14","dependencySha256":"eebade88f291cec281f38efe09597a107ce24904f28782d51405e739c4d37603","sourceSha256":"43afb91d79b2ae765b3a447549d9e1021a144a407cec5eb804be9fcf69a668a7","factorSha256":"80da7b01f57c852a1bca9a6f80a23636baef02091cd26880a7395c8331f5a20f","gwpSha256":"d87fb6c54a170e1dff70327bf475774febb3681a754cb8abec9c4c31efa3b908","sourceTitle":"EPA GHG Emission Factors Hub 2025","sourceSheet":"Emission Factors Hub","factorCells":["C38","E38","F38","G38"],"gwpCells":["E524","E525","E526"],"noteCells":["C94","C95","C99","E523","C10","C556"],"co2KgPerMmbtu":"53.06","ch4GramsPerMmbtu":"1.0","n2oGramsPerMmbtu":"0.10","ch4Gwp":"28","n2oGwp":"265","gwpAssessment":"IPCC AR5 100-year","status":"development_candidate_not_released","releaseEligible":false,"rights":"unresolved_for_factor_release"}'::jsonb$$;
create function neuvetra.m73_calculation(a jsonb,statement_hash text) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare q numeric;co2 numeric;ch4 numeric;n2o numeric;total numeric;i jsonb;body jsonb;begin
if a->'quantityMmbtu'='null' then return 'null'::jsonb;end if;q:=(a->>'quantityMmbtu')::numeric;co2:=q*53.06;ch4:=q/1000;n2o:=q/10000;total:=co2+ch4*28+n2o*265;
i:=jsonb_build_object('binding',a->'binding','period',a->'period','fuel',a->'fuel','heatBasis',a->'heatBasis','unit',a->'unit','quantityMmbtu',a->'quantityMmbtu','statementSha256',statement_hash);
body:=jsonb_build_object('profile','m73-decimal-result-v1','input',i,'inputSha256',neuvetra.m67_hash(i),'method',neuvetra.m73_method(),'gasResults',jsonb_build_object('co2',jsonb_build_object('mass',neuvetra.m73_exact(co2),'massUnit','kg CO2','co2e',neuvetra.m73_exact(co2),'co2eUnit','kg CO2e'),'ch4',jsonb_build_object('mass',neuvetra.m73_exact(ch4),'massUnit','kg CH4','co2e',neuvetra.m73_exact(ch4*28),'co2eUnit','kg CO2e'),'n2o',jsonb_build_object('mass',neuvetra.m73_exact(n2o),'massUnit','kg N2O','co2e',neuvetra.m73_exact(n2o*265),'co2eUnit','kg CO2e')),'total',jsonb_build_object('unrounded',neuvetra.m73_exact(total),'display',neuvetra.m73_display(total),'unit','kg CO2e','rounding','half_even_4dp'));
return body||jsonb_build_object('resultSha256',neuvetra.m67_hash(body));end $$;
create function neuvetra.m73_capacity(target_company uuid,new_bytes integer) returns void language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare used_bytes bigint;begin
select coalesce((select sum(octet_length(convert_to(export_text,'utf8'))+4096) from neuvetra.stationary_gas_versions where company_id=target_company),0)+coalesce((select sum(octet_length(convert_to(payload::text,'utf8'))) from neuvetra.stationary_gas_reports where company_id=target_company),0) into used_bytes;
if used_bytes+new_bytes>3800000 then raise exception 'history bytes limit' using errcode='54001';end if;end $$;
create function neuvetra.save_stationary_gas(target_company uuid,target_worksheet uuid,request jsonb,calculation jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();head record;prior record;old record;coverage jsonb;a jsonb;statement jsonb:='null';statement_id uuid;statement_text text;statement_hash text;expected_calc jsonb;body jsonb;v jsonb;contributors jsonb;fingerprint text;input_hash text;content_hash text;version_hash text;frozen text;new_id uuid:=gen_random_uuid();captured timestamptz;meter text;ref text;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;
perform neuvetra.m73_validate_request(request);fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));
select * into old from neuvetra.stationary_gas_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'save' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
coverage:=neuvetra.m73_coverage(target_company,request->'binding',true);a:=request-'expectedVersionId'-'expectedVersionSha256'-'correctionReason'-'idempotencyKey';
select * into head from neuvetra.stationary_gas_heads where company_id=target_company and id=target_worksheet for update;
select * into prior from neuvetra.stationary_gas_versions where company_id=target_company and id=head.version_id;
if target_worksheet is null then
if request->'expectedVersionId'<>'null' or exists(select 1 from neuvetra.stationary_gas_heads where company_id=target_company and source_id=(a#>>'{binding,sourceId}')::uuid)then raise exception 'source stream exists' using errcode='23505';end if;
if(select count(*) from neuvetra.stationary_gas_heads where company_id=target_company)>=3 then raise exception 'stream limit' using errcode='54000';end if;
insert into neuvetra.stationary_gas_heads(id,company_id,source_id) values(gen_random_uuid(),target_company,(a#>>'{binding,sourceId}')::uuid) returning * into head;
else
if head.id is null or head.source_id::text<>a#>>'{binding,sourceId}' then raise exception 'source identity conflict' using errcode='23505';end if;
select * into prior from neuvetra.stationary_gas_versions where company_id=target_company and id=head.version_id;
if prior.id::text is distinct from request->>'expectedVersionId' or prior.version_sha256 is distinct from request->>'expectedVersionSha256' then raise exception 'stale source version' using errcode='23505';end if;
if prior.payload->'activity'=a and prior.payload->'correctionReason'=request->'correctionReason' then raise exception 'no-op correction' using errcode='23505';end if;end if;
if(select count(*) from neuvetra.stationary_gas_versions where company_id=target_company)>=40 then raise exception 'version limit' using errcode='54000';end if;
if a->'statement'<>'null' then
statement_id:=gen_random_uuid();statement_text:=neuvetra.m73_statement(a,coverage);statement_hash:=encode(sha256(convert_to(statement_text,'utf8')),'hex');statement:=jsonb_build_object('id',statement_id,'profile','m73-synthetic-gas-statement-v1','input',a->'statement','locator','m73-statement:'||statement_id::text||':annual-activity','text',statement_text,'sha256',statement_hash,'byteLength',octet_length(convert_to(statement_text,'utf8')));
meter:=neuvetra.m67_hash(jsonb_build_array(lower(a#>>'{statement,issuer}'),lower(a#>>'{statement,meterLabel}'),'2025'));ref:=neuvetra.m67_hash(jsonb_build_array(lower(a#>>'{statement,issuer}'),lower(a#>>'{statement,reference}'),'2025'));
end if;
expected_calc:=neuvetra.m73_calculation(a,statement_hash);if calculation is distinct from expected_calc then raise exception 'calculation binding invalid' using errcode='22023';end if;
-- This update also enforces same company/meter/year and issuer/reference/year uniqueness.
update neuvetra.stationary_gas_heads set meter_key=meter,reference_key=ref where id=head.id;
captured:=date_trunc('milliseconds',clock_timestamp());
select jsonb_agg(x order by x collate "C") into contributors from(select distinct x from(select jsonb_array_elements_text(coalesce(prior.payload->'contributorIds','[]'))x union all select jsonb_array_elements_text(coverage->'contributorIds') union all select actor::text)a)a;
input_hash:=neuvetra.m67_hash(a);body:=jsonb_build_object('activity',a,'coverageVersion',coverage,'statement',statement,'calculation',calculation,'findings',neuvetra.m73_findings(a));content_hash:=neuvetra.m67_hash(body);
v:=jsonb_build_object('profile','synthetic-stationary-natural-gas-v1','id',new_id,'companyId',target_company,'worksheetId',head.id,'version',head.revision+1,'previousVersionId',prior.id,'previousVersionSha256',prior.version_sha256,'createdBy',actor,'createdAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'contributorIds',contributors,'correctionReason',request->'correctionReason','inputSha256',input_hash,'contentSha256',content_hash);version_hash:=neuvetra.m67_hash(v);
v:=(v-'profile')||body||jsonb_build_object('versionSha256',version_hash,'synthetic',true,'scope1Completeness','incomplete','corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','review',null);frozen:=neuvetra.m67_canonical(v);
if octet_length(convert_to(frozen,'utf8'))>102400 then raise exception 'version bytes limit' using errcode='54001';end if;perform neuvetra.m73_capacity(target_company,octet_length(convert_to(frozen,'utf8'))+4096);
if statement_id is not null then insert into neuvetra.stationary_gas_statements values(statement_id,target_company,statement,statement_hash,statement_text);end if;
insert into neuvetra.stationary_gas_versions values(new_id,target_company,head.id,head.revision+1,prior.id,(a#>>'{binding,coverageVersionId}')::uuid,statement_id,(a->>'quantityMmbtu')::numeric,v,input_hash,content_hash,version_hash,actor,captured,frozen);
insert into neuvetra.stationary_gas_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'save',fingerprint,new_id);insert into neuvetra.stationary_gas_audit values(gen_random_uuid(),target_company,new_id,'save',version_hash,actor,captured);
update neuvetra.stationary_gas_heads set version_id=new_id,revision=revision+1 where id=head.id;return new_id;end $$;
create function neuvetra.review_stationary_gas(target_company uuid,target_worksheet uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;old record;body jsonb;fingerprint text;digest text;new_id uuid:=gen_random_uuid();captured timestamptz;pair record;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.stationary_gas_heads where company_id=target_company and id=target_worksheet for update;
perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,decision,note,acknowledgedLimitations,idempotencyKey');for pair in select key,value from jsonb_each(request) where key<>'acknowledgedLimitations'loop if jsonb_typeof(pair.value)<>'string' then raise exception 'invalid review type' using errcode='22023';end if;end loop;
if request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or request->>'decision' not in('accepted_bounded_internal','changes_requested') or request->'acknowledgedLimitations'<>'["synthetic_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","combustion_only_upstream_excluded","requirements_not_determined","no_external_assurance"]'::jsonb then raise exception 'invalid review' using errcode='22023';end if;perform neuvetra.m73_text(request->'note',500);
fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','review','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.stationary_gas_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'review' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
select * into v from neuvetra.stationary_gas_versions where company_id=target_company and worksheet_id=target_worksheet and id=(request->>'versionId')::uuid;if not found or v.version_sha256<>request->>'expectedVersionSha256' or not exists(select 1 from neuvetra.stationary_gas_heads where id=target_worksheet and version_id=v.id) then raise exception 'stale review version' using errcode='23505';end if;
if v.payload->'contributorIds'?actor::text then raise exception 'contributor cannot review' using errcode='42501';end if;perform neuvetra.m73_coverage(target_company,v.payload#>'{activity,binding}',true);if request->>'decision'='accepted_bounded_internal' and v.payload->'calculation'='null' then raise exception 'missing calculation' using errcode='22023';end if;
captured:=date_trunc('milliseconds',clock_timestamp());body:=jsonb_build_object('id',new_id,'versionId',v.id,'versionSha256',v.version_sha256,'decision',request->'decision','note',request->'note','acknowledgedLimitations',request->'acknowledgedLimitations','reviewerId',actor,'reviewedAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));digest:=neuvetra.m67_hash(body||jsonb_build_object('profile','synthetic-stationary-natural-gas-v1','companyId',target_company));body:=body||jsonb_build_object('decisionSha256',digest);
insert into neuvetra.stationary_gas_reviews values(new_id,target_company,v.id,body,digest,actor,captured);insert into neuvetra.stationary_gas_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'review',fingerprint,new_id);insert into neuvetra.stationary_gas_audit values(gen_random_uuid(),target_company,new_id,'review',digest,actor,captured);return new_id;end $$;

create function neuvetra.m73_escape(v text) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select replace(replace(replace(replace(replace(coalesce(v,'Missing'),'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),chr(39),'&#39;')$$;
create function neuvetra.m73_pair(label text,v text) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '<dt>'||label||'</dt><dd>'||neuvetra.m73_escape(v)||'</dd>'$$;
create function neuvetra.m73_render_report(snapshot jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare v jsonb:=snapshot->'version';c jsonb:=v->'calculation';src jsonb;f jsonb;entity jsonb;boundary jsonb;fields jsonb;facts text;findings text;begin
select x into src from jsonb_array_elements(v#>'{coverageVersion,snapshot,sources}')x where x->>'id'=v#>>'{activity,binding,sourceId}';select x into f from jsonb_array_elements(v#>'{coverageVersion,snapshot,facilities}')x where x->>'id'=v#>>'{activity,binding,facilityId}';
select x into entity from jsonb_array_elements(v#>'{coverageVersion,snapshot,entities}')x where x->>'id'=v#>>'{activity,binding,entityId}';select x into boundary from jsonb_array_elements(v#>'{coverageVersion,snapshot,boundaryDecisions}')x where x->>'id'=v#>>'{activity,binding,boundaryDecisionId}';
facts:=neuvetra.m73_pair('Company',v#>>'{coverageVersion,snapshot,companyLabel}')||neuvetra.m73_pair('Entity',entity->>'legalName')||neuvetra.m73_pair('Boundary basis',boundary->>'reason')||neuvetra.m73_pair('Facility',f->>'name')||neuvetra.m73_pair('Source',src->>'name')||neuvetra.m73_pair('Reporting period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m73_pair('Coverage version',v#>>'{activity,binding,coverageVersionId}')||neuvetra.m73_pair('Source version',v->>'version')||neuvetra.m73_pair('Entered natural gas (MMBtu HHV)',v#>>'{activity,quantityMmbtu}')||neuvetra.m73_pair('Statement amount (MMBtu HHV)',v#>>'{activity,statement,statedQuantityMmbtu}')||neuvetra.m73_pair('Discrepancy explanation',coalesce(v#>>'{activity,discrepancyReason}','Not applicable'))||neuvetra.m73_pair('No-consumption explanation',coalesce(v#>>'{activity,zeroReason}','Not applicable'))||neuvetra.m73_pair('Exact source subtotal (kg CO2e)',c#>>'{total,unrounded}')||neuvetra.m73_pair('Displayed source subtotal (kg CO2e)',c#>>'{total,display}')||neuvetra.m73_pair('Review as captured',coalesce(snapshot#>>'{review,decision}','Unreviewed'))||neuvetra.m73_pair('Reviewer note',coalesce(snapshot#>>'{review,note}','Not yet reviewed'))||neuvetra.m73_pair('Review time',coalesce(snapshot#>>'{review,reviewedAt}','Not yet reviewed'))||neuvetra.m73_pair('Correction reason',coalesce(v->>'correctionReason','Not applicable'));
select coalesce(string_agg('<li>'||neuvetra.m73_escape(message)||'</li>','' order by ord),'') into findings from(select x->>'message' message,min(ord) ord from jsonb_array_elements((v->'findings')||(v#>'{coverageVersion,findings}')) with ordinality a(x,ord) group by x->>'message') deduplicated;
fields:=jsonb_build_object('facts',facts,'calculation',case when c='null' then '<p>Activity is missing; no emissions total was calculated.</p>' else '<table><thead><tr><th>Gas</th><th>Mass (kg)</th><th>kg CO2e</th></tr></thead><tbody>'||(select string_agg('<tr><th>'||label||'</th><td>'||neuvetra.m73_escape(c#>>array['gasResults',key,'mass'])||'</td><td>'||neuvetra.m73_escape(c#>>array['gasResults',key,'co2e'])||'</td></tr>','' order by ord) from(values('co2','CO2',1),('ch4','CH4',2),('n2o','N2O',3)) gases(key,label,ord))||'</tbody></table><p>Only the displayed total is rounded to four decimal places, using half-even rounding. Gas values and the exact total retain full precision.</p>' end,'statement',case when v->'statement'='null' then neuvetra.m73_pair('Evidence','No supporting statement entered') else neuvetra.m73_pair('Statement type','Synthetic — not a utility bill')||neuvetra.m73_pair('Issuer',v#>>'{activity,statement,issuer}')||neuvetra.m73_pair('Reference',v#>>'{activity,statement,reference}')||neuvetra.m73_pair('Dedicated meter',v#>>'{activity,statement,meterLabel}')||neuvetra.m73_pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m73_pair('Stated energy (MMBtu HHV)',v#>>'{activity,statement,statedQuantityMmbtu}')||neuvetra.m73_pair('Description',v#>>'{activity,statement,description}')||neuvetra.m73_pair('Retained statement locator',v#>>'{statement,locator}')||neuvetra.m73_pair('Statement SHA-256',v#>>'{statement,sha256}') end,'findings',findings,'snapshot',neuvetra.m73_escape(neuvetra.m67_canonical(snapshot)));
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>Synthetic stationary natural-gas source report</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:900px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}dt{font-weight:700}dd{margin:0 0 .6rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}li{margin:.3rem 0}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}pre{font-size:9pt}.technical-appendix:not([open]){display:none}}</style></head><body><h1>Stationary natural-gas source report — synthetic internal draft</h1><p>Development candidate · Not released. Corporate inventory incomplete. No filing determination or external assurance.</p><h2>Source and activity</h2><dl>'||(fields->>'facts')||'</dl><h2>Gas results and calculation trace</h2>'||(fields->>'calculation')||'<h2>Supporting synthetic statement</h2><dl>'||(fields->>'statement')||'</dl><h2>Corporate coverage remains incomplete</h2><p>Stationary combustion is partial. Mobile combustion, fugitive emissions including refrigerants, process emissions, other sources/facilities/periods, Scope 2 and all 15 Scope 3 categories remain unresolved or separately assessed. Combustion only; upstream fuel emissions excluded.</p><ul>'||(fields->>'findings')||'</ul><details class="technical-appendix"><summary>Exact version and provenance record</summary><pre>'||(fields->>'snapshot')||'</pre></details></body></html>';end $$;
create function neuvetra.create_stationary_gas_report(target_company uuid,target_worksheet uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;decision record;old record;new_id uuid:=gen_random_uuid();captured timestamptz;fingerprint text;snapshot jsonb;snapshot_text text;html text;body jsonb;digest text;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.stationary_gas_heads where company_id=target_company and id=target_worksheet for update;
perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,expectedDecisionId,expectedDecisionSha256,idempotencyKey');
if jsonb_typeof(request->'versionId')<>'string' or request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'idempotencyKey')<>'string' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'expectedVersionSha256')<>'string' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' then raise exception 'invalid report request' using errcode='22023';end if;
if request->'expectedDecisionId'='null' then if request->'expectedDecisionSha256'<>'null' then raise exception 'invalid decision pair' using errcode='23505';end if;else if jsonb_typeof(request->'expectedDecisionId')<>'string' or request->>'expectedDecisionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'expectedDecisionSha256')<>'string' or request->>'expectedDecisionSha256'!~'^[0-9a-f]{64}$' then raise exception 'invalid decision pair' using errcode='23505';end if;end if;
fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','report','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.stationary_gas_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'report' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
select * into v from neuvetra.stationary_gas_versions where company_id=target_company and worksheet_id=target_worksheet and id=(request->>'versionId')::uuid;if not found or v.version_sha256<>request->>'expectedVersionSha256' then raise exception 'report version conflict' using errcode='23505';end if;perform neuvetra.m73_coverage(target_company,v.payload#>'{activity,binding}',true);
select * into decision from neuvetra.stationary_gas_reviews where company_id=target_company and version_id=v.id;
if decision.id::text is distinct from request->>'expectedDecisionId' or decision.decision_sha256 is distinct from request->>'expectedDecisionSha256' then raise exception 'actual decision does not match report pin' using errcode='23505';end if;
snapshot:=jsonb_build_object('profile','m73-source-report-v1','version',v.payload,'review',decision.payload);snapshot_text:=neuvetra.m67_canonical(snapshot);html:=neuvetra.m73_render_report(snapshot);if octet_length(convert_to(html,'utf8'))>131072 then raise exception 'report bytes limit' using errcode='54001';end if;
captured:=date_trunc('milliseconds',clock_timestamp());body:=jsonb_build_object('id',new_id,'companyId',target_company,'worksheetId',target_worksheet,'versionId',v.id,'versionSha256',v.version_sha256,'decisionId',decision.id,'decisionSha256',decision.decision_sha256,'createdBy',actor,'createdAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'rendererVersion','m73-source-report-v1','htmlSha256',encode(sha256(convert_to(html,'utf8')),'hex'),'htmlByteLength',octet_length(convert_to(html,'utf8')),'snapshotSha256',encode(sha256(convert_to(snapshot_text,'utf8')),'hex'));
digest:=neuvetra.m67_hash(body||jsonb_build_object('profile','synthetic-stationary-natural-gas-v1'));body:=body||jsonb_build_object('html',html,'snapshotJson',snapshot_text,'reportSha256',digest);perform neuvetra.m73_capacity(target_company,octet_length(convert_to(body::text,'utf8')));
insert into neuvetra.stationary_gas_reports values(new_id,target_company,target_worksheet,v.id,decision.id,body,digest,actor,captured);insert into neuvetra.stationary_gas_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'report',fingerprint,new_id);insert into neuvetra.stationary_gas_audit values(gen_random_uuid(),target_company,new_id,'report',digest,actor,captured);return new_id;end $$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='neuvetra' and(p.proname like 'm73_%' or p.proname in('save_stationary_gas','review_stationary_gas','create_stationary_gas_report'))loop execute 'revoke all on function '||f.signature||' from public,authenticated,neuvetra_runtime';if f.proname in('save_stationary_gas','review_stationary_gas','create_stationary_gas_report')then execute 'grant execute on function '||f.signature||' to neuvetra_runtime';end if;end loop;end $$;
create function neuvetra.m73_lock(target_company uuid,writing boolean) returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing) then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;
revoke all on function neuvetra.m73_lock(uuid,boolean) from public,authenticated;grant execute on function neuvetra.m73_lock(uuid,boolean) to neuvetra_runtime;

-- M74 additive source-scoped synthetic mobile-diesel workpapers. Earlier history remains intact.
create table neuvetra.mobile_diesel_heads(id uuid primary key,company_id uuid not null references neuvetra.companies(id),source_id uuid not null,asset_id text not null,vehicle_key text not null,version_id uuid,revision integer not null default 0,fuel_reference_key text,mileage_reference_key text,unique(id,company_id),unique(company_id,source_id),unique(company_id,vehicle_key));
create table neuvetra.mobile_diesel_fuel_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.mobile_diesel_mileage_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.mobile_diesel_evidence_reservations(company_id uuid not null references neuvetra.companies(id),evidence_key text not null,worksheet_id uuid not null,statement_kind text not null check(statement_kind in('fuel','mileage')),created_at timestamptz not null,primary key(company_id,evidence_key));
create table neuvetra.mobile_diesel_versions(id uuid primary key,company_id uuid not null,worksheet_id uuid not null,version integer not null,previous_version_id uuid,coverage_version_id uuid not null,fuel_statement_id uuid,mileage_statement_id uuid,quantity_gallons numeric(15,3),distance_miles numeric(15,3),payload jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,worksheet_id,version),foreign key(worksheet_id,company_id) references neuvetra.mobile_diesel_heads(id,company_id),foreign key(previous_version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id),foreign key(coverage_version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id),foreign key(fuel_statement_id,company_id) references neuvetra.mobile_diesel_fuel_statements(id,company_id),foreign key(mileage_statement_id,company_id) references neuvetra.mobile_diesel_mileage_statements(id,company_id));
alter table neuvetra.mobile_diesel_heads add foreign key(version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id);
alter table neuvetra.mobile_diesel_evidence_reservations add foreign key(worksheet_id,company_id) references neuvetra.mobile_diesel_heads(id,company_id);
create table neuvetra.mobile_diesel_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),unique(company_id,version_id),foreign key(version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id));
create table neuvetra.mobile_diesel_reports(id uuid primary key,company_id uuid not null,worksheet_id uuid not null,version_id uuid not null,decision_id uuid,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(worksheet_id,company_id) references neuvetra.mobile_diesel_heads(id,company_id),foreign key(version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id),foreign key(decision_id,company_id) references neuvetra.mobile_diesel_reviews(id,company_id));
create unique index m74_report_state on neuvetra.mobile_diesel_reports(company_id,version_id,coalesce(decision_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table neuvetra.mobile_diesel_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.mobile_diesel_audit(id uuid primary key,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review','report')),record_sha256 text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));
do $$declare t text;begin foreach t in array array['mobile_diesel_heads','mobile_diesel_fuel_statements','mobile_diesel_mileage_statements','mobile_diesel_evidence_reservations','mobile_diesel_versions','mobile_diesel_reviews','mobile_diesel_reports','mobile_diesel_requests','mobile_diesel_audit'] loop
execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m74_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);
if t<>'mobile_diesel_heads' then execute format('create trigger m74_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;
create function neuvetra.m74_text(v jsonb,maximum integer) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s text:=v#>>'{}';begin if jsonb_typeof(v) is distinct from 'string' or length(s) not between 1 and maximum or s<>btrim(s) or s~U&'^[\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]|[\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]$' or s<>normalize(s,NFC) or s~'[[:cntrl:]]' then raise exception 'invalid text' using errcode='22023';end if;return s;end $$;
create function neuvetra.m74_quantity(v jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s text:=v#>>'{}';begin if jsonb_typeof(v) is distinct from 'string' or s!~'^(0|[1-9][0-9]{0,11})\.[0-9]{3}$' then raise exception 'invalid quantity' using errcode='22023';end if;return s;end $$;
create function neuvetra.m74_exact(v numeric) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case when position('.' in v::text)>0 then rtrim(rtrim(v::text,'0'),'.') else v::text end$$;
create function neuvetra.m74_display(v numeric) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$with x as(select v*10000 n),r as(select trunc(n) q,n-trunc(n) f from x) select to_char((q+case when f>0.5 or(f=0.5 and mod(q,2)=1)then 1 else 0 end)/10000,'FM999999999999999999999990.0000') from r$$;
create function neuvetra.m74_activity_status(a jsonb) returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_build_object('fuel',case when a->'quantityGallons'='null' then 'missing' when a->'fuelStatement'='null' then 'evidence_missing' when a->'fuelManualConfirmation'<>'true' then 'unconfirmed' when a->>'quantityGallons'<>a#>>'{fuelStatement,statedQuantityGallons}' then 'discrepancy' when a->>'quantityGallons'='0.000' then 'explicit_zero' else 'entered' end,'mileage',case when a->'distanceMiles'='null' then 'missing' when a->'mileageStatement'='null' then 'evidence_missing' when a->'mileageManualConfirmation'<>'true' then 'unconfirmed' when a->>'distanceMiles'<>a#>>'{mileageStatement,statedDistanceMiles}' then 'discrepancy' when a->>'distanceMiles'='0.000' then 'explicit_zero' else 'entered' end)$$;
create function neuvetra.m74_can_calculate(a jsonb) returns boolean language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select a->'quantityGallons'<>'null' and a->'distanceMiles'<>'null' and a->'fuelStatement'<>'null' and a->'mileageStatement'<>'null' and a->'fuelManualConfirmation'='true' and a->'mileageManualConfirmation'='true' and (a->>'quantityGallons'=a#>>'{fuelStatement,statedQuantityGallons}' or a->'fuelDiscrepancyReason'<>'null') and (a->>'distanceMiles'=a#>>'{mileageStatement,statedDistanceMiles}' or a->'mileageDiscrepancyReason'<>'null') and ((a->>'quantityGallons'<>'0.000' and a->>'distanceMiles'<>'0.000') or (a->>'quantityGallons'='0.000' and a->>'distanceMiles'='0.000' and a#>>'{fuelStatement,statedQuantityGallons}'='0.000' and a#>>'{mileageStatement,statedDistanceMiles}'='0.000' and a->'zeroReason'<>'null'))$$;
create function neuvetra.m74_findings(a jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare out jsonb:='[{"code":"scope1_incomplete","message":"This vehicle mobile-combustion subtotal does not complete stationary, mobile, fugitive or process emissions."},{"code":"method_not_released","message":"Factors and method are development candidates; no reporting or assurance determination."}]';s jsonb:=neuvetra.m74_activity_status(a);begin
if a->'quantityGallons'='null' then out:=out||'[{"code":"fuel_activity_missing","message":"Consumed gallons are missing; no emissions were calculated."}]';end if;if a->'distanceMiles'='null' then out:=out||'[{"code":"mileage_activity_missing","message":"Vehicle-miles are missing; no emissions were calculated."}]';end if;if a->'fuelStatement'='null' then out:=out||'[{"code":"fuel_statement_missing","message":"No synthetic annual fuel statement is retained."}]';end if;if a->'mileageStatement'='null' then out:=out||'[{"code":"mileage_statement_missing","message":"No synthetic annual mileage statement is retained."}]';end if;if s->>'fuel'='unconfirmed' then out:=out||'[{"code":"fuel_statement_unconfirmed","message":"The synthetic fuel assumptions have not been manually confirmed."}]';end if;if s->>'mileage'='unconfirmed' then out:=out||'[{"code":"mileage_statement_unconfirmed","message":"The synthetic mileage assumptions have not been manually confirmed."}]';end if;if s->>'fuel'='discrepancy' then out:=out||'[{"code":"fuel_activity_statement_discrepancy","message":"Entered and stated consumed gallons differ; the discrepancy remains unresolved."}]';end if;if s->>'mileage'='discrepancy' then out:=out||'[{"code":"mileage_activity_statement_discrepancy","message":"Entered and stated vehicle-miles differ; the discrepancy remains unresolved."}]';end if;if a->'quantityGallons'<>'null' and a->'distanceMiles'<>'null' and ((a->>'quantityGallons'='0.000')<>(a->>'distanceMiles'='0.000')) then out:=out||'[{"code":"mixed_zero_contradiction","message":"Zero in only one activity dimension is outside this bounded method; no emissions were calculated."}]';end if;if a->>'quantityGallons'='0.000' and a->>'distanceMiles'='0.000' and not neuvetra.m74_can_calculate(a) then out:=out||'[{"code":"unsupported_zero","message":"Zero activity needs matching zero statements, both confirmations and a no-operation/no-consumption reason."}]';end if;return out;end $$;
create function neuvetra.m74_coverage(target_company uuid,b jsonb,current_required boolean default true) returns jsonb language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare cv record;s jsonb;e jsonb;f jsonb;src jsonb;bd jsonb;rel jsonb;node text;seen text[]:='{}';pair record;begin
perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,entityId,facilityId,sourceId,boundaryDecisionId');for pair in select key,value from jsonb_each(b) loop if jsonb_typeof(pair.value)<>'string' or (pair.value#>>'{}') !~ (case when pair.key='coverageVersionSha256' then '^[0-9a-f]{64}$' else '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' end) then raise exception 'invalid binding' using errcode='22023';end if;end loop;
select * into cv from neuvetra.corporate_inventory_versions where company_id=target_company and id=(b->>'coverageVersionId')::uuid;if not found or cv.version_sha256<>b->>'coverageVersionSha256' then raise exception 'coverage binding conflict' using errcode='23505';end if;
if current_required and not exists(select 1 from neuvetra.corporate_inventory_heads where company_id=target_company and version_id=cv.id) then raise exception 'coverage changed' using errcode='23505';end if;
s:=cv.payload->'snapshot';perform neuvetra.m71_snapshot(s,null);if neuvetra.m67_hash(s)<>cv.content_sha256 or neuvetra.m67_hash((cv.payload-'snapshot'-'versionSha256')||jsonb_build_object('profile','synthetic-corporate-coverage-v1'))<>cv.version_sha256 or cv.export_text<>neuvetra.m67_canonical(cv.payload||jsonb_build_object('findings',neuvetra.m71_findings(s),'synthetic',true,'corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null,'review',null)) then raise exception 'coverage integrity failure' using errcode='22023';end if;
select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=b->>'entityId';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=b->>'facilityId';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=b->>'sourceId';select x into bd from jsonb_array_elements(s->'boundaryDecisions')x where x->>'id'=b->>'boundaryDecisionId';
if s->>'consolidationApproach'<>'operational_control' or e is null or f is null or src is null or bd is null or src->>'domain'<>'mobile_combustion' or src->>'entityId'<>e->>'id' or src->>'facilityId'<>f->>'id' or f->>'entityId'<>e->>'id' or bd->>'entityId'<>e->>'id' or e->>'countryCode'<>'US' or e->>'regionCode' is distinct from 'CA' or f->>'countryCode'<>'US' or f->>'regionCode' is distinct from 'CA' or bd->>'disposition'<>'included_activity' or bd->'reason'='null' or jsonb_array_length(bd->'evidenceRefs')=0 then raise exception 'source ineligible' using errcode='22023';end if;
for pair in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if pair.value->>'start'<>'2025-01-01' or pair.value->>'endExclusive'<>'2026-01-01' then raise exception 'unsupported period' using errcode='22023';end if;end loop;
node:=e->>'id';loop if node=any(seen) then raise exception 'relationship cycle' using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements(s->'relationships')x where x->>'childEntityId'=node;exit when rel is null;if rel->>'start'<>'2025-01-01' or rel->>'endExclusive'<>'2026-01-01' or rel->>'ownershipPercent' is distinct from '100' or rel->'controlFacts'='null' or jsonb_array_length(rel->'evidenceRefs')=0 then raise exception 'control basis incomplete' using errcode='22023';end if;node:=rel->>'parentEntityId';end loop;
return cv.export_text::jsonb;end $$;
create function neuvetra.m74_validate_request(r jsonb) returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare a jsonb;k text;begin
perform neuvetra.m71_keys(r,'profile,binding,period,vehicle,quantityGallons,distanceMiles,fuelStatement,mileageStatement,fuelManualConfirmation,mileageManualConfirmation,fuelDiscrepancyReason,mileageDiscrepancyReason,zeroReason,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey');
if r->>'profile' is distinct from 'synthetic-mobile-diesel-v1' or r->'period' is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or jsonb_typeof(r->'fuelManualConfirmation') is distinct from 'boolean' or jsonb_typeof(r->'mileageManualConfirmation') is distinct from 'boolean' or jsonb_typeof(r->'idempotencyKey') is distinct from 'string' or r->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid profile' using errcode='22023';end if;
a:=r->'vehicle';perform neuvetra.m71_keys(a,'assetId,vehicleClass,classificationBasis,modelYear,fuel,controlBasis');if jsonb_typeof(a->'assetId')<>'string' or a->>'assetId'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$' or a->>'vehicleClass'<>'Medium- and Heavy-Duty Vehicles' or jsonb_typeof(a->'modelYear')<>'number' or a->>'modelYear'!~'^(200[7-9]|201[0-9]|202[0-2])$' or a->>'fuel'<>'Fossil Diesel' or a->>'controlBasis'<>'owned_operational_control_full_year' then raise exception 'unsupported vehicle' using errcode='22023';end if;perform neuvetra.m74_text(a->'classificationBasis',500);
foreach k in array array['fuelDiscrepancyReason','mileageDiscrepancyReason','zeroReason','correctionReason']loop if r->k<>'null' then perform neuvetra.m74_text(r->k,500);end if;end loop;
if r->'expectedVersionId'='null' then if r->'expectedVersionSha256'<>'null' or r->'correctionReason'<>'null' then raise exception 'initial binding invalid' using errcode='22023';end if;else if jsonb_typeof(r->'expectedVersionId')<>'string' or r->>'expectedVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(r->'expectedVersionSha256')<>'string' or r->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or r->'correctionReason'='null' then raise exception 'correction binding invalid' using errcode='22023';end if;end if;
if r->'quantityGallons'<>'null' then perform neuvetra.m74_quantity(r->'quantityGallons');end if;if r->'distanceMiles'<>'null' then perform neuvetra.m74_quantity(r->'distanceMiles');end if;
if r->'fuelStatement'<>'null' then a:=r->'fuelStatement';perform neuvetra.m71_keys(a,'issuer,reference,statedQuantityGallons,description,consumptionBasis');perform neuvetra.m74_text(a->'issuer',120);perform neuvetra.m74_text(a->'reference',120);perform neuvetra.m74_quantity(a->'statedQuantityGallons');perform neuvetra.m74_text(a->'description',2000);if a->>'consumptionBasis'<>'dedicated_vehicle_consumed_no_adjustments' then raise exception 'fuel basis invalid' using errcode='22023';end if;end if;
if r->'mileageStatement'<>'null' then a:=r->'mileageStatement';perform neuvetra.m71_keys(a,'issuer,reference,statedDistanceMiles,description,distanceBasis');perform neuvetra.m74_text(a->'issuer',120);perform neuvetra.m74_text(a->'reference',120);perform neuvetra.m74_quantity(a->'statedDistanceMiles');perform neuvetra.m74_text(a->'description',2000);if a->>'distanceBasis'<>'dedicated_vehicle_annual_distance' then raise exception 'distance basis invalid' using errcode='22023';end if;end if;end $$;
create function neuvetra.m74_statement(a jsonb,coverage jsonb,kind text) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s jsonb:=coverage->'snapshot';e jsonb;f jsonb;src jsonb;body jsonb;begin select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=a#>>'{binding,entityId}';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=a#>>'{binding,facilityId}';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=a#>>'{binding,sourceId}';if kind='fuel' then body:=jsonb_build_object('profile','m74-synthetic-fuel-statement-v1','companyLabel',s->'companyLabel','entityLabel',e->'legalName','facilityLabel',f->'name','sourceLabel',src->'name','binding',a->'binding','period',a->'period','vehicle',a->'vehicle','quantityUnit','US_gallon','fuelComposition','fossil_diesel_only','statement',a->'fuelStatement');return 'SYNTHETIC — NOT A FUEL RECEIPT OR INDEPENDENT MEASUREMENT'||chr(10)||neuvetra.m67_canonical(body)||chr(10);elsif kind='mileage' then body:=jsonb_build_object('profile','m74-synthetic-mileage-statement-v1','companyLabel',s->'companyLabel','entityLabel',e->'legalName','facilityLabel',f->'name','sourceLabel',src->'name','binding',a->'binding','period',a->'period','vehicle',a->'vehicle','distanceUnit','vehicle_mile','tripCoverage','all_trip_locations_including_interstate','statement',a->'mileageStatement');return 'SYNTHETIC — NOT AN ODOMETER RECORD OR INDEPENDENT MEASUREMENT'||chr(10)||neuvetra.m67_canonical(body)||chr(10);else raise exception 'invalid statement kind' using errcode='22023';end if;end $$;

create function neuvetra.m74_method() returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '{"id":"mobile-diesel-combustion","version":"m74-development-v1","engineSha256":"1dc0bb7249d91e854004a8cadd34068be3fc03ecdd6e10b4cf297d375d7f52a6","sourceSha256":"43afb91d79b2ae765b3a447549d9e1021a144a407cec5eb804be9fcf69a668a7","factorSha256":"416931c40b347f1e22e9d4019ca1c28bd27ce40d7c16a3beeac3dadbbb783187","gwpSha256":"c151f9b90b23eba7ee9d36dd57a851ecf7a6f200c915579819b683d2b3b3c1c7","sourceTitle":"EPA GHG Emission Factors Hub 2025","sourceSheet":"Emission Factors Hub","factorCells":["C103:E103","C107:E107","C255:G256"],"gwpCells":["E523:E526"],"noteCells":["F3","F248:G248","C255:D256"],"co2KgPerGallon":"10.21","ch4GramsPerMile":"0.0095","n2oGramsPerMile":"0.0431","ch4Gwp":"28","n2oGwp":"265","gwpAssessment":"IPCC AR5 100-year","status":"development_candidate_not_released","releaseEligible":false,"rights":"unresolved_for_factor_release"}'::jsonb$$;
create function neuvetra.m74_calculation(a jsonb,fuel_hash text,mileage_hash text) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare gallons numeric;miles numeric;co2 numeric;ch4 numeric;n2o numeric;ch4e numeric;n2oe numeric;total numeric;i jsonb;body jsonb;begin
if not neuvetra.m74_can_calculate(a) then return 'null'::jsonb;end if;gallons:=(a->>'quantityGallons')::numeric;miles:=(a->>'distanceMiles')::numeric;co2:=gallons*10.21;ch4:=miles*0.0095/1000;n2o:=miles*0.0431/1000;ch4e:=ch4*28;n2oe:=n2o*265;total:=co2+ch4e+n2oe;
i:=jsonb_build_object('binding',a->'binding','period',a->'period','vehicle',a->'vehicle','quantityGallons',a->'quantityGallons','quantityUnit','US_gallon','distanceMiles',a->'distanceMiles','distanceUnit','vehicle_mile','fuelStatementSha256',fuel_hash,'mileageStatementSha256',mileage_hash);
body:=jsonb_build_object('profile','m74-decimal-result-v1','input',i,'inputSha256',neuvetra.m67_hash(i),'method',neuvetra.m74_method(),'gasResults',jsonb_build_object('co2',jsonb_build_object('mass',neuvetra.m74_exact(co2),'massUnit','kg CO2','co2e',neuvetra.m74_exact(co2),'co2eUnit','kg CO2e'),'ch4',jsonb_build_object('mass',neuvetra.m74_exact(ch4),'massUnit','kg CH4','co2e',neuvetra.m74_exact(ch4e),'co2eUnit','kg CO2e'),'n2o',jsonb_build_object('mass',neuvetra.m74_exact(n2o),'massUnit','kg N2O','co2e',neuvetra.m74_exact(n2oe),'co2eUnit','kg CO2e')),'total',jsonb_build_object('unrounded',neuvetra.m74_exact(total),'display',neuvetra.m74_display(total),'unit','kg CO2e','rounding','half_even_4dp'));
return body||jsonb_build_object('resultSha256',neuvetra.m67_hash(body));end $$;
create function neuvetra.m74_capacity(target_company uuid,new_bytes integer) returns void language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare used_bytes bigint;begin
select coalesce((select sum(octet_length(convert_to(export_text,'utf8'))+4096) from neuvetra.mobile_diesel_versions where company_id=target_company),0)+coalesce((select sum(octet_length(convert_to(payload::text,'utf8'))) from neuvetra.mobile_diesel_reports where company_id=target_company),0) into used_bytes;
if used_bytes+new_bytes>3800000 then raise exception 'history bytes limit' using errcode='54001';end if;end $$;
create function neuvetra.save_mobile_diesel(target_company uuid,target_worksheet uuid,request jsonb,calculation jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();head neuvetra.mobile_diesel_heads%rowtype;prior neuvetra.mobile_diesel_versions%rowtype;old neuvetra.mobile_diesel_requests%rowtype;reservation neuvetra.mobile_diesel_evidence_reservations%rowtype;coverage jsonb;a jsonb;fuel_statement jsonb:='null';mileage_statement jsonb:='null';fuel_id uuid;mileage_id uuid;fuel_text text;mileage_text text;fuel_hash text;mileage_hash text;fuel_key text;mileage_key text;vehicle_key text;expected_calc jsonb;body jsonb;v jsonb;contributors jsonb;fingerprint text;input_hash text;content_hash text;version_hash text;frozen text;new_id uuid:=gen_random_uuid();captured timestamptz;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;
perform neuvetra.m74_validate_request(request);fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.mobile_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'save' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
coverage:=neuvetra.m74_coverage(target_company,request->'binding',true);a:=request-'expectedVersionId'-'expectedVersionSha256'-'correctionReason'-'idempotencyKey';vehicle_key:=neuvetra.m67_hash(jsonb_build_array(a#>>'{vehicle,assetId}','Fossil Diesel','2025'));select * into head from neuvetra.mobile_diesel_heads where company_id=target_company and id=target_worksheet for update;
if target_worksheet is null then if request->'expectedVersionId'<>'null' or exists(select 1 from neuvetra.mobile_diesel_heads where company_id=target_company and source_id=(a#>>'{binding,sourceId}')::uuid) then raise exception 'source stream exists' using errcode='23505';end if;if(select count(*) from neuvetra.mobile_diesel_heads where company_id=target_company)>=3 then raise exception 'stream limit' using errcode='54000';end if;insert into neuvetra.mobile_diesel_heads(id,company_id,source_id,asset_id,vehicle_key)values(gen_random_uuid(),target_company,(a#>>'{binding,sourceId}')::uuid,a#>>'{vehicle,assetId}',vehicle_key)returning * into head;
else if head.id is null or head.source_id::text<>a#>>'{binding,sourceId}' or head.asset_id<>a#>>'{vehicle,assetId}' or head.vehicle_key<>vehicle_key then raise exception 'immutable vehicle identity conflict' using errcode='23505';end if;select * into prior from neuvetra.mobile_diesel_versions where company_id=target_company and id=head.version_id;if prior.id::text is distinct from request->>'expectedVersionId' or prior.version_sha256 is distinct from request->>'expectedVersionSha256' then raise exception 'stale source version' using errcode='23505';end if;if prior.payload->'activity'=a then raise exception 'no-op correction' using errcode='23505';end if;end if;
if(select count(*) from neuvetra.mobile_diesel_versions where company_id=target_company)>=40 then raise exception 'version limit' using errcode='54000';end if;
if a->'fuelStatement'<>'null' then fuel_id:=gen_random_uuid();fuel_text:=neuvetra.m74_statement(a,coverage,'fuel');fuel_hash:=encode(sha256(convert_to(fuel_text,'utf8')),'hex');fuel_statement:=jsonb_build_object('id',fuel_id,'profile','m74-synthetic-fuel-statement-v1','input',a->'fuelStatement','locator','m74-fuel-statement:'||fuel_id::text||':annual-activity','text',fuel_text,'sha256',fuel_hash,'byteLength',octet_length(convert_to(fuel_text,'utf8')));fuel_key:=neuvetra.m67_hash(jsonb_build_array(lower(a#>>'{fuelStatement,issuer}'),lower(a#>>'{fuelStatement,reference}'),'2025'));select * into reservation from neuvetra.mobile_diesel_evidence_reservations where company_id=target_company and evidence_key=fuel_key for update;if found and(reservation.worksheet_id<>head.id or reservation.statement_kind<>'fuel')then raise exception 'evidence identity conflict' using errcode='23505';elsif not found then insert into neuvetra.mobile_diesel_evidence_reservations values(target_company,fuel_key,head.id,'fuel',clock_timestamp());end if;end if;
if a->'mileageStatement'<>'null' then mileage_id:=gen_random_uuid();mileage_text:=neuvetra.m74_statement(a,coverage,'mileage');mileage_hash:=encode(sha256(convert_to(mileage_text,'utf8')),'hex');mileage_statement:=jsonb_build_object('id',mileage_id,'profile','m74-synthetic-mileage-statement-v1','input',a->'mileageStatement','locator','m74-mileage-statement:'||mileage_id::text||':annual-activity','text',mileage_text,'sha256',mileage_hash,'byteLength',octet_length(convert_to(mileage_text,'utf8')));mileage_key:=neuvetra.m67_hash(jsonb_build_array(lower(a#>>'{mileageStatement,issuer}'),lower(a#>>'{mileageStatement,reference}'),'2025'));select * into reservation from neuvetra.mobile_diesel_evidence_reservations where company_id=target_company and evidence_key=mileage_key for update;if found and(reservation.worksheet_id<>head.id or reservation.statement_kind<>'mileage')then raise exception 'evidence identity conflict' using errcode='23505';elsif not found then insert into neuvetra.mobile_diesel_evidence_reservations values(target_company,mileage_key,head.id,'mileage',clock_timestamp());end if;end if;
expected_calc:=neuvetra.m74_calculation(a,fuel_hash,mileage_hash);if calculation is distinct from expected_calc then raise exception 'calculation binding invalid' using errcode='22023';end if;update neuvetra.mobile_diesel_heads set fuel_reference_key=fuel_key,mileage_reference_key=mileage_key where id=head.id;captured:=date_trunc('milliseconds',clock_timestamp());
select jsonb_agg(x order by x collate "C") into contributors from(select distinct x from(select jsonb_array_elements_text(coalesce(prior.payload->'contributorIds','[]'))x union all select jsonb_array_elements_text(coverage->'contributorIds') union all select actor::text)a)a;input_hash:=neuvetra.m67_hash(a);body:=jsonb_build_object('activity',a,'activityStatus',neuvetra.m74_activity_status(a),'coverageVersion',coverage,'fuelStatement',fuel_statement,'mileageStatement',mileage_statement,'calculation',calculation,'findings',neuvetra.m74_findings(a));content_hash:=neuvetra.m67_hash(body);
v:=jsonb_build_object('profile','synthetic-mobile-diesel-v1','id',new_id,'companyId',target_company,'worksheetId',head.id,'version',head.revision+1,'previousVersionId',prior.id,'previousVersionSha256',prior.version_sha256,'createdBy',actor,'createdAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'contributorIds',contributors,'correctionReason',request->'correctionReason','inputSha256',input_hash,'contentSha256',content_hash);version_hash:=neuvetra.m67_hash(v);v:=(v-'profile')||body||jsonb_build_object('versionSha256',version_hash,'synthetic',true,'scope1Completeness','incomplete','corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','review',null);frozen:=neuvetra.m67_canonical(v);
if octet_length(convert_to(frozen,'utf8'))>102400 then raise exception 'version bytes limit' using errcode='54001';end if;perform neuvetra.m74_capacity(target_company,octet_length(convert_to(frozen,'utf8'))+4096);if fuel_id is not null then insert into neuvetra.mobile_diesel_fuel_statements values(fuel_id,target_company,fuel_statement,fuel_hash,fuel_text);end if;if mileage_id is not null then insert into neuvetra.mobile_diesel_mileage_statements values(mileage_id,target_company,mileage_statement,mileage_hash,mileage_text);end if;
insert into neuvetra.mobile_diesel_versions values(new_id,target_company,head.id,head.revision+1,prior.id,(a#>>'{binding,coverageVersionId}')::uuid,fuel_id,mileage_id,(a->>'quantityGallons')::numeric,(a->>'distanceMiles')::numeric,v,input_hash,content_hash,version_hash,actor,captured,frozen);insert into neuvetra.mobile_diesel_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'save',fingerprint,new_id);insert into neuvetra.mobile_diesel_audit values(gen_random_uuid(),target_company,new_id,'save',version_hash,actor,captured);update neuvetra.mobile_diesel_heads set version_id=new_id,revision=revision+1 where id=head.id;return new_id;end $$;
create function neuvetra.review_mobile_diesel(target_company uuid,target_worksheet uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;old record;body jsonb;fingerprint text;digest text;new_id uuid:=gen_random_uuid();captured timestamptz;pair record;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.mobile_diesel_heads where company_id=target_company and id=target_worksheet for update;
perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,decision,note,acknowledgedLimitations,idempotencyKey');for pair in select key,value from jsonb_each(request) where key<>'acknowledgedLimitations'loop if jsonb_typeof(pair.value)<>'string' then raise exception 'invalid review type' using errcode='22023';end if;end loop;
if request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or request->>'decision' not in('accepted_bounded_internal','changes_requested') or request->'acknowledgedLimitations'<>'["synthetic_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","vehicle_mobile_combustion_subtotal_only","upstream_fuel_emissions_excluded","requirements_not_determined","no_external_assurance"]'::jsonb then raise exception 'invalid review' using errcode='22023';end if;perform neuvetra.m74_text(request->'note',500);
fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','review','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.mobile_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'review' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
select * into v from neuvetra.mobile_diesel_versions where company_id=target_company and worksheet_id=target_worksheet and id=(request->>'versionId')::uuid;if not found or v.version_sha256<>request->>'expectedVersionSha256' or not exists(select 1 from neuvetra.mobile_diesel_heads where id=target_worksheet and version_id=v.id) then raise exception 'stale review version' using errcode='23505';end if;
if v.payload->'contributorIds'?actor::text then raise exception 'contributor cannot review' using errcode='42501';end if;perform neuvetra.m74_coverage(target_company,v.payload#>'{activity,binding}',true);if request->>'decision'='accepted_bounded_internal' and v.payload->'calculation'='null' then raise exception 'missing calculation' using errcode='22023';end if;
captured:=date_trunc('milliseconds',clock_timestamp());body:=jsonb_build_object('id',new_id,'versionId',v.id,'versionSha256',v.version_sha256,'decision',request->'decision','note',request->'note','acknowledgedLimitations',request->'acknowledgedLimitations','reviewerId',actor,'reviewedAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));digest:=neuvetra.m67_hash(body||jsonb_build_object('profile','synthetic-mobile-diesel-v1','companyId',target_company));body:=body||jsonb_build_object('decisionSha256',digest);
insert into neuvetra.mobile_diesel_reviews values(new_id,target_company,v.id,body,digest,actor,captured);insert into neuvetra.mobile_diesel_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'review',fingerprint,new_id);insert into neuvetra.mobile_diesel_audit values(gen_random_uuid(),target_company,new_id,'review',digest,actor,captured);return new_id;end $$;

create function neuvetra.m74_escape(v text) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select replace(replace(replace(replace(replace(coalesce(v,'Missing'),'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),chr(39),'&#39;')$$;
create function neuvetra.m74_pair(label text,v text) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '<dt>'||label||'</dt><dd>'||neuvetra.m74_escape(v)||'</dd>'$$;
create function neuvetra.m74_render_report(snapshot jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare v jsonb:=snapshot->'version';c jsonb:=v->'calculation';m jsonb:=c->'method';src jsonb;f jsonb;entity jsonb;boundary jsonb;facts text;calc text;fuel text;mileage text;method text;findings text;begin
select x into src from jsonb_array_elements(v#>'{coverageVersion,snapshot,sources}')x where x->>'id'=v#>>'{activity,binding,sourceId}';select x into f from jsonb_array_elements(v#>'{coverageVersion,snapshot,facilities}')x where x->>'id'=v#>>'{activity,binding,facilityId}';select x into entity from jsonb_array_elements(v#>'{coverageVersion,snapshot,entities}')x where x->>'id'=v#>>'{activity,binding,entityId}';select x into boundary from jsonb_array_elements(v#>'{coverageVersion,snapshot,boundaryDecisions}')x where x->>'id'=v#>>'{activity,binding,boundaryDecisionId}';
facts:=neuvetra.m74_pair('Company',v#>>'{coverageVersion,snapshot,companyLabel}')||neuvetra.m74_pair('Entity',entity->>'legalName')||neuvetra.m74_pair('Boundary basis',boundary->>'reason')||neuvetra.m74_pair('Base facility',f->>'name')||neuvetra.m74_pair('Source',src->>'name')||neuvetra.m74_pair('Reporting period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m74_pair('All-trip location basis','All vehicle travel, including interstate trips')||neuvetra.m74_pair('Coverage version',v#>>'{activity,binding,coverageVersionId}')||neuvetra.m74_pair('Source version',v->>'version')||neuvetra.m74_pair('Vehicle asset ID',v#>>'{activity,vehicle,assetId}')||neuvetra.m74_pair('Vehicle class',v#>>'{activity,vehicle,vehicleClass}')||neuvetra.m74_pair('Classification basis',v#>>'{activity,vehicle,classificationBasis}')||neuvetra.m74_pair('Model year',v#>>'{activity,vehicle,modelYear}')||neuvetra.m74_pair('Fuel',v#>>'{activity,vehicle,fuel}')||neuvetra.m74_pair('Control basis',v#>>'{activity,vehicle,controlBasis}')||neuvetra.m74_pair('Entered consumed fuel (U.S. gallons)',v#>>'{activity,quantityGallons}')||neuvetra.m74_pair('Fuel statement amount (U.S. gallons)',v#>>'{activity,fuelStatement,statedQuantityGallons}')||neuvetra.m74_pair('Fuel dimension status',v#>>'{activityStatus,fuel}')||neuvetra.m74_pair('Fuel discrepancy explanation',coalesce(v#>>'{activity,fuelDiscrepancyReason}','Not applicable'))||neuvetra.m74_pair('Entered distance (vehicle-miles)',v#>>'{activity,distanceMiles}')||neuvetra.m74_pair('Mileage statement amount (vehicle-miles)',v#>>'{activity,mileageStatement,statedDistanceMiles}')||neuvetra.m74_pair('Mileage dimension status',v#>>'{activityStatus,mileage}')||neuvetra.m74_pair('Mileage discrepancy explanation',coalesce(v#>>'{activity,mileageDiscrepancyReason}','Not applicable'))||neuvetra.m74_pair('No-operation/no-consumption explanation',coalesce(v#>>'{activity,zeroReason}','Not applicable'))||neuvetra.m74_pair('Exact vehicle mobile-combustion subtotal (kg CO2e)',c#>>'{total,unrounded}')||neuvetra.m74_pair('Displayed vehicle mobile-combustion subtotal (kg CO2e)',c#>>'{total,display}')||neuvetra.m74_pair('Review as captured',coalesce(snapshot#>>'{review,decision}','Unreviewed'))||neuvetra.m74_pair('Reviewer note',coalesce(snapshot#>>'{review,note}','Not yet reviewed'))||neuvetra.m74_pair('Review time',coalesce(snapshot#>>'{review,reviewedAt}','Not yet reviewed'))||neuvetra.m74_pair('Correction reason',coalesce(v->>'correctionReason','Not applicable'));
if c='null' then calc:='<p>Required compatible activity and evidence are incomplete or contradictory; no emissions total was calculated.</p>';method:=neuvetra.m74_pair('Method','No calculation was admitted; method remains a development candidate');else calc:='<table><thead><tr><th>Gas</th><th>Mass</th><th>kg CO2e</th></tr></thead><tbody>'||(select string_agg('<tr><th>'||label||'</th><td>'||neuvetra.m74_escape(c#>>array['gasResults',key,'mass'])||' '||neuvetra.m74_escape(c#>>array['gasResults',key,'massUnit'])||'</td><td>'||neuvetra.m74_escape(c#>>array['gasResults',key,'co2e'])||'</td></tr>','' order by ord)from(values('co2','CO2',1),('ch4','CH4',2),('n2o','N2O',3))gases(key,label,ord))||'</tbody></table><p>CO2 uses consumed U.S. gallons. CH4 and N2O use vehicle-miles. Only the displayed total is rounded to four decimal places, using half-even rounding. Gas values and the exact total retain full precision.</p>';method:=neuvetra.m74_pair('Method ID and version',(m->>'id')||' / '||(m->>'version'))||neuvetra.m74_pair('Source',m->>'sourceTitle')||neuvetra.m74_pair('Source edition','January 15, 2025')||neuvetra.m74_pair('Workbook SHA-256',m->>'sourceSha256')||neuvetra.m74_pair('Factor locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'factorCells')with ordinality x(value,ord)))||neuvetra.m74_pair('GWP locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'gwpCells')with ordinality x(value,ord)))||neuvetra.m74_pair('Note locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'noteCells')with ordinality x(value,ord)))||neuvetra.m74_pair('Factor normalization','Published displayed decimals corroborated by the EPA 2025 PDF; XLSX binary tails are not used')||neuvetra.m74_pair('CO2 factor',(m->>'co2KgPerGallon')||' kg CO2 per U.S. gallon')||neuvetra.m74_pair('CH4 factor',(m->>'ch4GramsPerMile')||' g CH4 per vehicle-mile')||neuvetra.m74_pair('N2O factor',(m->>'n2oGramsPerMile')||' g N2O per vehicle-mile')||neuvetra.m74_pair('GWP basis',(m->>'gwpAssessment')||'; CH4 '||(m->>'ch4Gwp')||', N2O '||(m->>'n2oGwp'))||neuvetra.m74_pair('Rights status',m->>'rights')||neuvetra.m74_pair('Method status',m->>'status');end if;
fuel:=case when v->'fuelStatement'='null' then neuvetra.m74_pair('Evidence','No supporting fuel statement retained') else neuvetra.m74_pair('Statement type','Synthetic human-entered fuel statement')||neuvetra.m74_pair('Issuer',v#>>'{activity,fuelStatement,issuer}')||neuvetra.m74_pair('Reference',v#>>'{activity,fuelStatement,reference}')||neuvetra.m74_pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m74_pair('Stated consumed fuel (U.S. gallons)',v#>>'{activity,fuelStatement,statedQuantityGallons}')||neuvetra.m74_pair('Description',v#>>'{activity,fuelStatement,description}')||neuvetra.m74_pair('Manual confirmation',v#>>'{activity,fuelManualConfirmation}')||neuvetra.m74_pair('Retained statement locator',v#>>'{fuelStatement,locator}')||neuvetra.m74_pair('Statement SHA-256',v#>>'{fuelStatement,sha256}')||neuvetra.m74_pair('Statement byte length',v#>>'{fuelStatement,byteLength}') end;
mileage:=case when v->'mileageStatement'='null' then neuvetra.m74_pair('Evidence','No supporting mileage statement retained') else neuvetra.m74_pair('Statement type','Synthetic human-entered mileage statement')||neuvetra.m74_pair('Issuer',v#>>'{activity,mileageStatement,issuer}')||neuvetra.m74_pair('Reference',v#>>'{activity,mileageStatement,reference}')||neuvetra.m74_pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m74_pair('Stated distance (vehicle-miles)',v#>>'{activity,mileageStatement,statedDistanceMiles}')||neuvetra.m74_pair('Description',v#>>'{activity,mileageStatement,description}')||neuvetra.m74_pair('Manual confirmation',v#>>'{activity,mileageManualConfirmation}')||neuvetra.m74_pair('Retained statement locator',v#>>'{mileageStatement,locator}')||neuvetra.m74_pair('Statement SHA-256',v#>>'{mileageStatement,sha256}')||neuvetra.m74_pair('Statement byte length',v#>>'{mileageStatement,byteLength}') end;
select coalesce(string_agg('<li>'||neuvetra.m74_escape(message)||'</li>','' order by ord),'')into findings from(select x->>'message' message,min(ord)ord from jsonb_array_elements((v->'findings')||(v#>'{coverageVersion,findings}'))with ordinality a(x,ord)group by x->>'message')deduplicated;
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>Synthetic vehicle mobile-combustion source report</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:900px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}dt{font-weight:700}dd{margin:0 0 .6rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}li{margin:.3rem 0}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}pre{font-size:9pt}.technical-appendix:not([open]){display:none}}</style></head><body><h1>Vehicle mobile-combustion subtotal — synthetic internal draft</h1><p>Development candidate · Not released. Corporate inventory incomplete. No filing determination or external assurance.</p><h2>Source, vehicle and activity</h2><dl>'||facts||'</dl><h2>Gas results and calculation trace</h2>'||calc||'<h2>Supporting synthetic fuel statement</h2><dl>'||fuel||'</dl><h2>Supporting synthetic mileage statement</h2><dl>'||mileage||'</dl><h2>Method and provenance</h2><dl>'||method||'</dl><h2>Corporate coverage remains incomplete</h2><p>This report covers one bounded vehicle source. Other stationary, mobile, fugitive, process, facility and period sources remain unresolved or separately assessed. Combustion only; upstream fuel emissions are excluded.</p><ul>'||findings||'</ul><details class="technical-appendix"><summary>Exact version and provenance record</summary><pre>'||neuvetra.m74_escape(neuvetra.m67_canonical(snapshot))||'</pre></details></body></html>';end $$;
create function neuvetra.create_mobile_diesel_report(target_company uuid,target_worksheet uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;decision record;old record;new_id uuid:=gen_random_uuid();captured timestamptz;fingerprint text;snapshot jsonb;snapshot_text text;html text;body jsonb;digest text;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.mobile_diesel_heads where company_id=target_company and id=target_worksheet for update;
perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,expectedDecisionId,expectedDecisionSha256,idempotencyKey');
if jsonb_typeof(request->'versionId')<>'string' or request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'idempotencyKey')<>'string' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'expectedVersionSha256')<>'string' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' then raise exception 'invalid report request' using errcode='22023';end if;
if request->'expectedDecisionId'='null' then if request->'expectedDecisionSha256'<>'null' then raise exception 'invalid decision pair' using errcode='23505';end if;else if jsonb_typeof(request->'expectedDecisionId')<>'string' or request->>'expectedDecisionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'expectedDecisionSha256')<>'string' or request->>'expectedDecisionSha256'!~'^[0-9a-f]{64}$' then raise exception 'invalid decision pair' using errcode='23505';end if;end if;
fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','report','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.mobile_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'report' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
select * into v from neuvetra.mobile_diesel_versions where company_id=target_company and worksheet_id=target_worksheet and id=(request->>'versionId')::uuid;if not found or v.version_sha256<>request->>'expectedVersionSha256' then raise exception 'report version conflict' using errcode='23505';end if;perform neuvetra.m74_coverage(target_company,v.payload#>'{activity,binding}',true);
select * into decision from neuvetra.mobile_diesel_reviews where company_id=target_company and version_id=v.id;
if decision.id::text is distinct from request->>'expectedDecisionId' or decision.decision_sha256 is distinct from request->>'expectedDecisionSha256' then raise exception 'actual decision does not match report pin' using errcode='23505';end if;
snapshot:=jsonb_build_object('profile','m74-mobile-source-report-v1','version',v.payload,'review',decision.payload);snapshot_text:=neuvetra.m67_canonical(snapshot);html:=neuvetra.m74_render_report(snapshot);if octet_length(convert_to(html,'utf8'))>131072 then raise exception 'report bytes limit' using errcode='54001';end if;
captured:=date_trunc('milliseconds',clock_timestamp());body:=jsonb_build_object('id',new_id,'companyId',target_company,'worksheetId',target_worksheet,'versionId',v.id,'versionSha256',v.version_sha256,'decisionId',decision.id,'decisionSha256',decision.decision_sha256,'createdBy',actor,'createdAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'rendererVersion','m74-mobile-source-report-v1','htmlSha256',encode(sha256(convert_to(html,'utf8')),'hex'),'htmlByteLength',octet_length(convert_to(html,'utf8')),'snapshotSha256',encode(sha256(convert_to(snapshot_text,'utf8')),'hex'));
digest:=neuvetra.m67_hash(body||jsonb_build_object('profile','synthetic-mobile-diesel-v1'));body:=body||jsonb_build_object('html',html,'snapshotJson',snapshot_text,'reportSha256',digest);perform neuvetra.m74_capacity(target_company,octet_length(convert_to(body::text,'utf8')));
insert into neuvetra.mobile_diesel_reports values(new_id,target_company,target_worksheet,v.id,decision.id,body,digest,actor,captured);insert into neuvetra.mobile_diesel_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'report',fingerprint,new_id);insert into neuvetra.mobile_diesel_audit values(gen_random_uuid(),target_company,new_id,'report',digest,actor,captured);return new_id;end $$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='neuvetra' and(p.proname like 'm74_%' or p.proname in('save_mobile_diesel','review_mobile_diesel','create_mobile_diesel_report'))loop execute 'revoke all on function '||f.signature||' from public,authenticated,neuvetra_runtime';if f.proname in('save_mobile_diesel','review_mobile_diesel','create_mobile_diesel_report')then execute 'grant execute on function '||f.signature||' to neuvetra_runtime';end if;end loop;end $$;
create function neuvetra.m74_lock(target_company uuid,writing boolean) returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing) then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;
revoke all on function neuvetra.m74_lock(uuid,boolean) from public,authenticated;grant execute on function neuvetra.m74_lock(uuid,boolean) to neuvetra_runtime;

-- Additive synthetic controlled-fleet roster and reconciliation reports.
create table neuvetra.controlled_fleet_heads(company_id uuid primary key references neuvetra.companies(id),id uuid not null,version_id uuid,revision integer not null default 0,unique(id,company_id));
create table neuvetra.controlled_fleet_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.controlled_fleet_versions(id uuid primary key,company_id uuid not null,roster_id uuid not null,version integer not null,previous_version_id uuid,coverage_version_id uuid not null,statement_id uuid,payload jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,roster_id,version),foreign key(roster_id,company_id) references neuvetra.controlled_fleet_heads(id,company_id),foreign key(previous_version_id,company_id) references neuvetra.controlled_fleet_versions(id,company_id),foreign key(coverage_version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id),foreign key(statement_id,company_id) references neuvetra.controlled_fleet_statements(id,company_id));
alter table neuvetra.controlled_fleet_heads add constraint controlled_fleet_head_version_fk foreign key(version_id,company_id) references neuvetra.controlled_fleet_versions(id,company_id) deferrable initially deferred;
create table neuvetra.controlled_fleet_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),unique(company_id,version_id),foreign key(version_id,company_id) references neuvetra.controlled_fleet_versions(id,company_id));
create table neuvetra.controlled_fleet_reports(id uuid primary key,company_id uuid not null,roster_id uuid not null,version_id uuid not null,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(roster_id,company_id) references neuvetra.controlled_fleet_heads(id,company_id),foreign key(version_id,company_id) references neuvetra.controlled_fleet_versions(id,company_id));
create table neuvetra.controlled_fleet_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.controlled_fleet_audit(id uuid primary key,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review','report')),record_sha256 text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));

do $$declare t text;begin foreach t in array array['controlled_fleet_heads','controlled_fleet_statements','controlled_fleet_versions','controlled_fleet_reviews','controlled_fleet_reports','controlled_fleet_requests','controlled_fleet_audit'] loop execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m75_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);if t<>'controlled_fleet_heads' then execute format('create trigger m75_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;

create function neuvetra.m75_lock(target_company uuid,writing boolean) returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing) then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.controlled_fleet_heads where company_id=target_company for update;perform id from neuvetra.mobile_diesel_heads where company_id=target_company order by id for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;

create function neuvetra.m75_exact_keys(value jsonb, expected text[]) returns boolean language sql immutable set search_path=pg_catalog as $$select jsonb_typeof(value)='object' and (select coalesce(array_agg(k order by k),'{}'::text[]) from jsonb_object_keys(value) k)=(select coalesce(array_agg(k order by k),'{}'::text[]) from unnest(expected) k)$$;

create function neuvetra.m75_text_valid(value jsonb,max_chars integer) returns boolean language sql immutable set search_path=pg_catalog as $$select jsonb_typeof(value)='string' and length(btrim(value#>>'{}')) between 1 and max_chars and value#>>'{}'=btrim(value#>>'{}') and normalize(value#>>'{}',NFC)=value#>>'{}' and value#>>'{}'!~'[\u0000-\u001F\u007F-\u009F]'$$;

create function neuvetra.m75_activity_valid(activity jsonb) returns boolean language plpgsql immutable set search_path=pg_catalog,neuvetra as $$declare s jsonb;a jsonb;l jsonb;p jsonb;begin if not neuvetra.m75_exact_keys(activity,array['profile','coverageVersionId','coverageVersionSha256','period','rosterStatement','manualConfirmation','links']) or activity->>'profile' is distinct from 'synthetic-controlled-fleet-v1' or activity->>'coverageVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or activity->>'coverageVersionSha256'!~'^[0-9a-f]{64}$' or activity->'period' is distinct from jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01') or jsonb_typeof(activity->'manualConfirmation') is distinct from 'boolean' or jsonb_typeof(activity->'links') is distinct from 'array' or jsonb_array_length(activity->'links')>25 then return false;end if;s:=activity->'rosterStatement';if s='null'::jsonb then return activity->'links'='[]'::jsonb;end if;if not neuvetra.m75_exact_keys(s,array['issuer','reference','description','discoveryBasis','coveredEntityIds','completeness','allTripLocationsIncluded','assets']) or not neuvetra.m75_text_valid(s->'issuer',120) or not neuvetra.m75_text_valid(s->'reference',120) or not neuvetra.m75_text_valid(s->'description',2000) or not neuvetra.m75_text_valid(s->'discoveryBasis',2000) or jsonb_typeof(s->'coveredEntityIds') is distinct from 'array' or s->>'completeness' not in('declared_complete','partial','unknown') or jsonb_typeof(s->'allTripLocationsIncluded') is distinct from 'boolean' or jsonb_typeof(s->'assets') is distinct from 'array' or jsonb_array_length(s->'assets')>25 then return false;end if;if exists(select 1 from jsonb_array_elements(s->'coveredEntityIds') x where jsonb_typeof(x)<>'string' or x#>>'{}'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') or s->'coveredEntityIds' is distinct from (select coalesce(jsonb_agg(x order by x#>>'{}' collate "C"),'[]'::jsonb) from(select distinct x from jsonb_array_elements(s->'coveredEntityIds') x) q) then return false;end if;for a in select x from jsonb_array_elements(s->'assets') x loop if not neuvetra.m75_exact_keys(a,array['rowId','assetId','aliases','entityId','facilityId','period','mode','vehicleClass','modelYear','fuel','controlBasis','classificationBasis','controlExplanation']) or a->>'rowId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or (a->'assetId'<>'null'::jsonb and (jsonb_typeof(a->'assetId')<>'string' or a->>'assetId'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$')) or jsonb_typeof(a->'aliases') is distinct from 'array' or jsonb_array_length(a->'aliases')>8 or exists(select 1 from jsonb_array_elements(a->'aliases') x where jsonb_typeof(x)<>'string' or x#>>'{}'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$') or a->'aliases' is distinct from (select coalesce(jsonb_agg(x order by x#>>'{}' collate "C"),'[]'::jsonb) from(select distinct x from jsonb_array_elements(a->'aliases') x) q) or (a->'assetId'<>'null'::jsonb and (a->'aliases') ? (a->>'assetId')) or (a->'entityId'<>'null'::jsonb and (jsonb_typeof(a->'entityId')<>'string' or a->>'entityId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) or (a->'facilityId'<>'null'::jsonb and (jsonb_typeof(a->'facilityId')<>'string' or a->>'facilityId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) or (a->'period'<>'null'::jsonb and (not neuvetra.m75_exact_keys(a->'period',array['start','endExclusive']) or a#>>'{period,start}'!~'^\d{4}-\d{2}-\d{2}$' or a#>>'{period,endExclusive}'!~'^\d{4}-\d{2}-\d{2}$' or to_char(to_date(a#>>'{period,start}','FXYYYY-MM-DD'),'YYYY-MM-DD')<>a#>>'{period,start}' or to_char(to_date(a#>>'{period,endExclusive}','FXYYYY-MM-DD'),'YYYY-MM-DD')<>a#>>'{period,endExclusive}' or a#>>'{period,start}'>=a#>>'{period,endExclusive}')) or a->>'mode' not in('on_road','off_road','rail','marine','air','other','unknown') or (a->'vehicleClass'<>'null'::jsonb and not neuvetra.m75_text_valid(a->'vehicleClass',100)) or (a->'modelYear'<>'null'::jsonb and (jsonb_typeof(a->'modelYear')<>'number' or a->>'modelYear'!~'^\d{4}$' or (a->>'modelYear')::integer not between 1900 and 2100)) or (a->'fuel'<>'null'::jsonb and not neuvetra.m75_text_valid(a->'fuel',100)) or a->>'controlBasis' not in('owned_operational_control_full_year','other_control_arrangement','unknown') or (a->'classificationBasis'<>'null'::jsonb and not neuvetra.m75_text_valid(a->'classificationBasis',500)) or (a->'controlExplanation'<>'null'::jsonb and not neuvetra.m75_text_valid(a->'controlExplanation',500)) then return false;end if;end loop;if (select count(*) from jsonb_array_elements(s->'assets'))<>(select count(distinct x->>'rowId') from jsonb_array_elements(s->'assets') x) then return false;end if;for l in select x from jsonb_array_elements(activity->'links') x loop if not neuvetra.m75_exact_keys(l,array['rowId','sourceId']) or l->>'rowId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or (l->'sourceId'<>'null'::jsonb and (jsonb_typeof(l->'sourceId')<>'string' or l->>'sourceId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) then return false;end if;end loop;return (select count(*) from jsonb_array_elements(activity->'links'))=(select count(distinct x->>'rowId') from jsonb_array_elements(activity->'links') x) and (select jsonb_agg(to_jsonb(x->>'rowId') order by x->>'rowId' collate "C") from jsonb_array_elements(activity->'links') x)=(select jsonb_agg(to_jsonb(x->>'rowId') order by x->>'rowId' collate "C") from jsonb_array_elements(s->'assets') x);exception when others then return false;end $$;

create function neuvetra.m75_current_dependencies(target_company uuid) returns jsonb language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$with coverage as(select v.id,v.version_sha256,r.id review_id,r.decision_sha256 from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on(v.company_id=h.company_id and v.id=h.version_id) left join neuvetra.corporate_inventory_reviews r on(r.company_id=v.company_id and r.version_id=v.id) where h.company_id=target_company),pins as(select coalesce(jsonb_agg(jsonb_build_object('worksheetId',v.worksheet_id,'sourceId',v.payload#>'{activity,binding,sourceId}','assetId',v.payload#>'{activity,vehicle,assetId}','version',jsonb_build_object('id',v.id,'sha256',v.version_sha256),'decision',case when r.id is null then 'null'::jsonb else jsonb_build_object('id',r.id,'sha256',r.decision_sha256)end) order by v.worksheet_id),'[]'::jsonb) value from neuvetra.mobile_diesel_heads h join neuvetra.mobile_diesel_versions v on(v.company_id=h.company_id and v.id=h.version_id) left join neuvetra.mobile_diesel_reviews r on(r.company_id=v.company_id and r.version_id=v.id) where h.company_id=target_company),body as(select jsonb_build_object('coveragePin',case when c.id is null then 'null'::jsonb else jsonb_build_object('id',c.id,'sha256',c.version_sha256)end,'coverageReviewPin',case when c.review_id is null then 'null'::jsonb else jsonb_build_object('id',c.review_id,'sha256',c.decision_sha256)end,'workpaperPins',p.value) value from pins p left join coverage c on true) select value||jsonb_build_object('dependencySha256',neuvetra.m67_hash(value)) from body$$;

create function neuvetra.m75_local_blocked(target_company uuid,activity jsonb) returns boolean language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$with cv as(select v.payload from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company),assets as(select a from jsonb_array_elements(coalesce(activity#>'{rosterStatement,assets}','[]'::jsonb)) a),links as(select l from jsonb_array_elements(activity->'links') l),identities as(select a->>'assetId' id from assets where a->>'assetId' is not null union all select alias#>>'{}' from assets cross join lateral jsonb_array_elements(a->'aliases') alias) select activity->'rosterStatement'='null'::jsonb or activity->>'manualConfirmation'<>'true' or jsonb_array_length(coalesce(activity#>'{rosterStatement,assets}','[]'::jsonb))=0 or activity#>>'{rosterStatement,completeness}'<>'declared_complete' or activity#>>'{rosterStatement,allTripLocationsIncluded}'<>'true' or activity#>'{rosterStatement,coveredEntityIds}' is distinct from (select jsonb_agg(to_jsonb(e->>'id') order by e->>'id') from cv,jsonb_array_elements(cv.payload#>'{snapshot,entities}') e) or exists(select 1 from assets a where a.a->>'assetId' is null or a.a->>'entityId' is null or a.a->>'facilityId' is null or a.a->'period'='null'::jsonb or a.a->>'mode'='unknown' or a.a->>'vehicleClass' is null or a.a->>'modelYear' is null or a.a->>'fuel' is null or a.a->>'controlBasis'='unknown' or a.a->>'classificationBasis' is null or a.a->>'controlExplanation' is null or not exists(select 1 from cv,jsonb_array_elements(cv.payload#>'{snapshot,entities}') e where e->>'id'=a.a->>'entityId') or not exists(select 1 from cv,jsonb_array_elements(cv.payload#>'{snapshot,facilities}') f where f->>'id'=a.a->>'facilityId' and f->>'entityId'=a.a->>'entityId') or not exists(select 1 from links l,cv,jsonb_array_elements(cv.payload#>'{snapshot,sources}') s where l.l->>'rowId'=a.a->>'rowId' and l.l->>'sourceId'=s->>'id' and s->>'domain'='mobile_combustion') or a.a->>'mode'<>'on_road' or a.a->>'vehicleClass'<>'Medium- and Heavy-Duty Vehicles' or (a.a->>'modelYear')::integer not between 2007 and 2022 or a.a->>'fuel'<>'Fossil Diesel' or a.a->>'controlBasis'<>'owned_operational_control_full_year' or a.a#>>'{period,start}'<>'2025-01-01' or a.a#>>'{period,endExclusive}'<>'2026-01-01') or exists(select 1 from identities group by id having count(*)>1) or exists(select 1 from links where l->>'sourceId' is not null group by l->>'sourceId' having count(*)>1)$$;

-- Root-authored fragment for backend integration. Exact TS roster-local findings.
-- Inputs must pass the save contract before this function is called.
create function neuvetra.m75_roster_findings(activity jsonb, coverage jsonb)
returns jsonb language plpgsql immutable set search_path=pg_catalog as $$
declare
 out_findings jsonb := '[]'::jsonb;
 statement jsonb := activity->'rosterStatement';
 asset jsonb;
 row_key text;
 source_id text;
 expected_entities jsonb;
 supported boolean;
 identity_row record;
begin

if statement is null or statement='null'::jsonb then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_statement_missing','rowKey',null,'message','The declared controlled-vehicle roster statement is missing.','blocking',true)); return out_findings; end if;
if activity->>'manualConfirmation' is distinct from 'true' then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_unconfirmed','rowKey',null,'message','Confirm the complete synthetic roster declaration.','blocking',true)); end if;
if jsonb_array_length(statement->'assets')=0 then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_empty','rowKey',null,'message','An empty roster cannot establish a zero fleet.','blocking',true)); end if;
if statement->>'completeness' is distinct from 'declared_complete' then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_not_declared_complete','rowKey',null,'message','The roster population is partial or unknown.','blocking',true)); end if;
if statement->>'allTripLocationsIncluded' is distinct from 'true' then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','trip_locations_incomplete','rowKey',null,'message','The roster declaration must cover all trip locations, including interstate travel.','blocking',true)); end if;
select coalesce(jsonb_agg(to_jsonb(e->>'id') order by (e->>'id') collate "C"),'[]'::jsonb) into expected_entities from jsonb_array_elements(coverage#>'{snapshot,entities}') e;
if statement->'coveredEntityIds' is distinct from expected_entities then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','entity_population_incomplete','rowKey',null,'message','Every entity in the bound corporate register needs a roster population declaration.','blocking',true)); end if;
for asset in select a from jsonb_array_elements(statement->'assets') with ordinality x(a,n) order by n loop
 row_key := 'roster:'||(asset->>'rowId');
 select l->>'sourceId' into source_id from jsonb_array_elements(activity->'links') with ordinality x(l,n) where l->>'rowId'=asset->>'rowId' order by n desc limit 1;
 if nullif(asset->>'entityId','') is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=asset->>'entityId') then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','unknown_entity','rowKey',row_key,'message','The declared entity is not in the bound corporate register.','blocking',true)); end if;
 if nullif(asset->>'facilityId','') is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=asset->>'facilityId' and (nullif(asset->>'entityId','') is null or f->>'entityId'=asset->>'entityId')) then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','facility_conflict','rowKey',row_key,'message','The declared facility is missing or belongs to another entity.','blocking',true)); end if;
 if nullif(source_id,'') is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,sources}') s where s->>'id'=source_id and s->>'domain'='mobile_combustion') then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','source_conflict','rowKey',row_key,'message','The mapped source is missing or is not mobile combustion.','blocking',true)); end if;
 if nullif(asset->>'assetId','') is null then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','asset_identity_unknown','rowKey',row_key,'message','Stable vehicle identity is unknown.','blocking',true)); end if;
 if nullif(asset->>'entityId','') is null or nullif(asset->>'facilityId','') is null or coalesce(asset->'period','null'::jsonb)='null'::jsonb or asset->>'mode'='unknown' or nullif(asset->>'vehicleClass','') is null or asset->>'modelYear' is null or nullif(asset->>'fuel','') is null or asset->>'controlBasis'='unknown' or nullif(asset->>'classificationBasis','') is null or nullif(asset->>'controlExplanation','') is null then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','vehicle_facts_unknown','rowKey',row_key,'message','One or more required vehicle, period, classification or control facts are unknown.','blocking',true)); end if;
 supported := coalesce(asset->>'mode'='on_road' and asset->>'vehicleClass'='Medium- and Heavy-Duty Vehicles' and (asset->>'modelYear')::integer between 2007 and 2022 and asset->>'fuel'='Fossil Diesel' and asset->>'controlBasis'='owned_operational_control_full_year' and asset->'period'=jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01'),false);
 if not supported and nullif(asset->>'assetId','') is not null and asset->>'mode'<>'unknown' and nullif(asset->>'vehicleClass','') is not null and asset->>'modelYear' is not null and nullif(asset->>'fuel','') is not null and asset->>'controlBasis'<>'unknown' and coalesce(asset->'period','null'::jsonb)<>'null'::jsonb then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','vehicle_profile_unsupported','rowKey',row_key,'message','The controlled vehicle is outside the current M74 candidate profile.','blocking',true)); end if;
 if nullif(source_id,'') is null then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','source_missing','rowKey',row_key,'message','No current corporate mobile source is mapped to this roster row.','blocking',true)); end if;
end loop;
-- Match JavaScript Map insertion order: first occurrence of each identity,
-- then every occurrence's original asset/alias order (including duplicates).
for identity_row in
 with assets as(select a,n from jsonb_array_elements(statement->'assets') with ordinality x(a,n)),
 identities as(
  select a->>'assetId' identity,a->>'rowId' row_id,n asset_order,0::bigint alias_order from assets where nullif(a->>'assetId','') is not null
  union all select alias#>>'{}',a->>'rowId',n,k from assets cross join lateral jsonb_array_elements(a->'aliases') with ordinality x(alias,k)
 ), positions as(select *,row_number() over(order by asset_order,alias_order) position from identities),
 repeated as(select *,count(*) over(partition by identity) occurrences,min(position) over(partition by identity) first_position from positions)
 select identity,row_id from repeated where occurrences>1 order by first_position,position
loop

 out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','duplicate_asset_identity','rowKey','roster:'||identity_row.row_id,'message','Declared asset identity '||identity_row.identity||' appears in multiple roster rows.','blocking',true));
end loop;
for identity_row in
 with assets as(select a,n from jsonb_array_elements(statement->'assets') with ordinality x(a,n)),
 mapped as(select a->>'rowId' row_id,n,(select l->>'sourceId' from jsonb_array_elements(activity->'links') with ordinality x(l,k) where l->>'rowId'=a->>'rowId' order by k desc limit 1) identity from assets),
 repeated as(select *,count(*) over(partition by identity) occurrences,min(n) over(partition by identity) first_position from mapped where nullif(identity,'') is not null)
 select identity,row_id from repeated where occurrences>1 order by first_position,n
loop

 out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','duplicate_source_mapping','rowKey','roster:'||identity_row.row_id,'message','Corporate mobile source '||identity_row.identity||' is mapped to multiple roster rows.','blocking',true));
end loop;
return out_findings;
end $$;

create function neuvetra.m75_acceptance_ready(target_company uuid,version_payload jsonb) returns boolean language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$with cv as(select v.payload from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id join neuvetra.corporate_inventory_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company and r.payload->>'decision'='accepted_bounded_internal'),assets as(select a from jsonb_array_elements(version_payload#>'{activity,rosterStatement,assets}') a),links as(select l from jsonb_array_elements(version_payload#>'{activity,links}') l),sources as(select s from cv,jsonb_array_elements(cv.payload#>'{snapshot,sources}') s where s->>'domain'='mobile_combustion'),wps as(select v.payload p,r.payload review from neuvetra.mobile_diesel_heads h join neuvetra.mobile_diesel_versions v on v.id=h.version_id and v.company_id=h.company_id join neuvetra.mobile_diesel_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company) select exists(select 1 from cv) and version_payload->'findings'='[]'::jsonb and version_payload#>>'{activity,manualConfirmation}'='true' and version_payload#>>'{activity,rosterStatement,completeness}'='declared_complete' and version_payload#>>'{activity,rosterStatement,allTripLocationsIncluded}'='true' and (select count(*) from assets)=(select count(*) from links) and (select count(*) from assets)=(select count(*) from sources) and (select count(*) from assets)=(select count(*) from wps) and not exists(select 1 from sources s where not exists(select 1 from cv,jsonb_array_elements(cv.payload#>'{snapshot,coverageItems}') i where i->>'sourceId'=s.s->>'id' and i->>'disposition'='included_activity')) and version_payload#>'{activity,rosterStatement,coveredEntityIds}'=(select jsonb_agg(to_jsonb(e->>'id') order by e->>'id') from cv,jsonb_array_elements(cv.payload#>'{snapshot,entities}') e) and not exists(select 1 from assets a where a.a->>'mode'<>'on_road' or a.a->>'vehicleClass'<>'Medium- and Heavy-Duty Vehicles' or (a.a->>'modelYear')::integer not between 2007 and 2022 or a.a->>'fuel'<>'Fossil Diesel' or a.a->>'controlBasis'<>'owned_operational_control_full_year' or a.a#>>'{period,start}'<>'2025-01-01' or a.a#>>'{period,endExclusive}'<>'2026-01-01') and not exists(select 1 from(select id,count(*) n from(select a->>'assetId' id from assets where a->>'assetId' is not null union all select alias#>>'{}' from assets cross join lateral jsonb_array_elements(a->'aliases') alias) identities group by id having count(*)>1) d) and not exists(select 1 from links group by l->>'sourceId' having count(*)>1) and not exists(select 1 from links l where not exists(select 1 from assets a where a.a->>'rowId'=l.l->>'rowId') or not exists(select 1 from sources s where s.s->>'id'=l.l->>'sourceId') or not exists(select 1 from wps w,assets a where a.a->>'rowId'=l.l->>'rowId' and w.p#>>'{activity,binding,sourceId}'=l.l->>'sourceId' and (w.p#>>'{activity,vehicle,assetId}'=a.a->>'assetId' or (a.a->'aliases') ? (w.p#>>'{activity,vehicle,assetId}')) and w.p#>>'{activity,binding,entityId}'=a.a->>'entityId' and w.p#>>'{activity,binding,facilityId}'=a.a->>'facilityId' and w.p#>>'{activity,vehicle,vehicleClass}'=a.a->>'vehicleClass' and w.p#>>'{activity,vehicle,modelYear}'=a.a->>'modelYear' and w.p#>>'{activity,vehicle,fuel}'=a.a->>'fuel' and w.p#>>'{activity,vehicle,controlBasis}'=a.a->>'controlBasis' and w.p->'calculation'<>'null'::jsonb and w.p#>>'{activityStatus,fuel}' in('entered','explicit_zero') and w.p#>>'{activityStatus,mileage}' in('entered','explicit_zero') and w.p#>>'{activity,binding,coverageVersionId}'=(neuvetra.m75_current_dependencies(target_company)#>>'{coveragePin,id}') and w.p#>>'{activity,binding,coverageVersionSha256}'=(neuvetra.m75_current_dependencies(target_company)#>>'{coveragePin,sha256}') and w.review->>'decision'='accepted_bounded_internal' and not exists(select 1 from jsonb_array_elements(w.p->'findings') f where f->>'code' not in('scope1_incomplete','method_not_released'))))$$;

