 deps:=neuvetra.m75_current_dependencies(target_company);activity:=request-array['expectedDependencySha256','expectedVersionId','expectedVersionSha256','correctionReason','idempotencyKey'];content:=jsonb_build_object('activity',version_payload->'activity','dependencies',version_payload->'dependencies','statement',version_payload->'statement','findings',version_payload->'findings');
