 if request->>'coverageVersionId' is distinct from deps#>>'{coveragePin,id}' or request->>'coverageVersionSha256' is distinct from deps#>>'{coveragePin,sha256}' then raise exception 'stale roster dependencies' using errcode='23505';end if;
 fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save','actor',actor,'companyId',target_company,'rosterId',target_roster,'request',request-'idempotencyKey'));select * into old from neuvetra.controlled_fleet_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'save' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
 select * into head from neuvetra.controlled_fleet_heads where company_id=target_company for update;if head.id is null then if target_roster is not null or request->'expectedVersionId' is distinct from 'null'::jsonb then raise exception 'invalid first roster' using errcode='23505';end if;insert into neuvetra.controlled_fleet_heads(company_id,id) values(target_company,(version_payload->>'rosterId')::uuid) returning * into head;else if target_roster is distinct from head.id then raise exception 'roster conflict' using errcode='23505';end if;select * into prior from neuvetra.controlled_fleet_versions where company_id=target_company and id=head.version_id;if prior.id::text is distinct from request->>'expectedVersionId' or prior.version_sha256 is distinct from request->>'expectedVersionSha256' then raise exception 'stale roster' using errcode='23505';end if;if head.revision>=40 then raise exception 'roster history capacity reached' using errcode='22023';end if;if prior.id is not null and (request->'correctionReason'='null'::jsonb or prior.payload->'statement'<>'null'::jsonb and version_payload->'statement'='null'::jsonb or prior.payload->'activity'=activity and prior.payload->'dependencies'=deps or exists(select 1 from jsonb_array_elements(prior.payload#>'{activity,rosterStatement,assets}') old_asset where not exists(select 1 from jsonb_array_elements(version_payload#>'{activity,rosterStatement,assets}') new_asset where new_asset->>'rowId'=old_asset->>'rowId'))) then raise exception 'invalid roster correction' using errcode='22023';end if;end if;if octet_length(convert_to(neuvetra.m67_canonical(version_payload),'utf8'))>100000 then raise exception 'roster version too large' using errcode='22023';end if;if (select coalesce(sum(octet_length(convert_to(export_text,'utf8'))),0) from neuvetra.controlled_fleet_versions where company_id=target_company)+(select coalesce(sum(octet_length(convert_to(payload->>'html','utf8'))+octet_length(convert_to(payload->>'snapshotJson','utf8'))),0) from neuvetra.controlled_fleet_reports where company_id=target_company)+octet_length(convert_to(neuvetra.m67_canonical(version_payload),'utf8'))>3800000 then raise exception 'fleet history capacity reached' using errcode='22023';end if;select coalesce(jsonb_agg(to_jsonb(x) order by x),'[]'::jsonb) into contributors from(select distinct x from(select jsonb_array_elements_text(coalesce(prior.payload->'contributorIds','[]'::jsonb)) x union all select jsonb_array_elements_text(coalesce((select v.payload->'contributorIds' from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company),'[]'::jsonb)) union all select jsonb_array_elements_text(v.payload->'contributorIds') from neuvetra.mobile_diesel_heads h join neuvetra.mobile_diesel_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company union all select actor::text) q) s;
